
const $ = q => document.querySelector(q);
const clamp = (v,a,b)=>Math.max(a,Math.min(b,v));
const DPR = Math.min(2, window.devicePixelRatio||1);

/* ---------- audio ----------
   A burning grove full of squirrels can ask for dozens of sounds in the same handful of
   milliseconds. Every voice used to be built raw and wired straight to the destination, which
   caused three separate problems at once: the summed signal ran past full scale and crackled,
   oscillators starting and stopping at full amplitude clicked, and the sounds that actually
   matter (taking a hit, a wave ending, a purchase) were buried under incidental chatter.

   The fix is the standard game-audio arrangement:
     - one limiter on the master so stacked voices compress instead of clipping
     - separate buses, so critical sounds can duck the busy layer rather than compete with it
     - a polyphony ceiling, with the least important voices dropped first under load
     - coalescing, so thirty identical chirps in one instant become one chirp
     - a short attack/release on every voice, which is what removes the clicking
   Priorities: 0 = incidental chatter, 1 = normal, 2 = critical (never dropped, always ducks). */
let AC=null, MASTER=null, SFXBUS=null, PRIOBUS=null, MUSICBUS=null;
const SFX_MAX_VOICES=16;     // hard polyphony ceiling
const SFX_COALESCE=0.055;    // seconds — identical sounds inside this window collapse into one
const SFX_LAST=Object.create(null);
// Voices are tracked by when they finish on the audio clock rather than by a timer. A timer-based
// release stops running the moment the main thread is busy — exactly when the park is at its
// loudest — which would leak the voice count upward and silence the game until it caught up.
const SFX_ENDS=[];
function sfxActive(now){
  while(SFX_ENDS.length && SFX_ENDS[0]<=now) SFX_ENDS.shift();
  return SFX_ENDS.length;
}
function audioInit(){
  if(AC) return AC;
  AC = new (window.AudioContext||window.webkitAudioContext)();
  MASTER=AC.createDynamicsCompressor();
  // limiter-shaped: hard ratio, no knee, fast attack — catches transient stacks without pumping
  MASTER.threshold.value=-10; MASTER.knee.value=0; MASTER.ratio.value=20;
  MASTER.attack.value=0.003; MASTER.release.value=0.25;
  MASTER.connect(AC.destination);
  SFXBUS=AC.createGain();   SFXBUS.gain.value=1;   SFXBUS.connect(MASTER);
  PRIOBUS=AC.createGain();  PRIOBUS.gain.value=1;  PRIOBUS.connect(MASTER);
  MUSICBUS=AC.createGain(); MUSICBUS.gain.value=1; MUSICBUS.connect(MASTER);
  return AC;
}
function sfxOut(prio){ return prio>=2 ? PRIOBUS : SFXBUS; }
// a critical sound briefly pushes the busy layer down, so it cuts through a swarm instead of
// being one more voice inside it
function sfxDuck(){
  if(!AC) return;
  const t=AC.currentTime;
  for(const [bus,to,back] of [[SFXBUS,0.38,0.34],[MUSICBUS,0.45,0.40]]){
    bus.gain.cancelScheduledValues(t);
    bus.gain.setValueAtTime(bus.gain.value,t);
    bus.gain.linearRampToValueAtTime(to,t+0.02);
    bus.gain.linearRampToValueAtTime(1,t+back);
  }
}
function sfxAllow(key,prio,now){
  const live=sfxActive(now);
  if(prio>=2){ SFX_LAST[key]=now; return true; }        // critical always speaks
  const last=SFX_LAST[key];
  if(last!=null && now-last<SFX_COALESCE) return false;  // the same sound, the same instant
  if(live>=SFX_MAX_VOICES) return false;
  if(prio<=0 && live>=SFX_MAX_VOICES*0.55) return false;   // chatter yields first
  SFX_LAST[key]=now;
  return true;
}
function sfxVoice(endT){
  SFX_ENDS.push(endT);
  SFX_ENDS.sort((a,b)=>a-b);      // at most a handful of entries, so this stays trivial
}
function beep(f=440,d=.06,type="square",g=.04,opt){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const prio = opt && opt.prio!=null ? opt.prio : 1;
    // sounds group by timbre and rough pitch, so near-identical chirps coalesce automatically
    // without every one of the hundred call sites having to name itself
    const key = (opt && opt.key) || (type+"|"+Math.round(f/60));
    const now=AC.currentTime;
    if(!sfxAllow(key,prio,now)) return;
    if(prio>=2) sfxDuck();
    const o=AC.createOscillator(), gn=AC.createGain();
    o.type=type; o.frequency.value=f;
    // a few ms of attack and release: a square wave switched on at full amplitude clicks, and
    // thirty of those at once is most of what "harsh when it gets busy" actually was
    const atk=Math.min(0.006,d*0.25), rel=Math.min(0.02,d*0.35);
    gn.gain.setValueAtTime(0.0001,now);
    gn.gain.linearRampToValueAtTime(g,now+atk);
    gn.gain.setValueAtTime(g,now+Math.max(atk,d-rel));
    gn.gain.linearRampToValueAtTime(0.0001,now+d);
    o.connect(gn); gn.connect(sfxOut(prio));
    o.start(now); o.stop(now+d+0.02);
    sfxVoice(now+d+0.02);
  }catch(e){}
}
// a short burst of filtered noise — the breathy "chuff" texture layered under bark() and
// other percussive hits, so they don't read as pure tone
function noiseBurst(dur,freq,q,gain,t0){
  const buf=AC.createBuffer(1, Math.max(1,Math.floor(AC.sampleRate*dur)), AC.sampleRate);
  const d=buf.getChannelData(0);
  for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*(1-i/d.length);
  const src=AC.createBufferSource(); src.buffer=buf;
  const f=AC.createBiquadFilter(); f.type="bandpass"; f.frequency.value=freq; f.Q.value=q;
  const g=AC.createGain(); g.gain.setValueAtTime(gain,t0); g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  src.connect(f); f.connect(g); g.connect(PRIOBUS);
  src.start(t0);
}
// a real synthesised woof — a fast downward sawtooth sweep (the tonal body) layered with a
// bandpassed noise burst (the breathy chuff) — instead of a flat beep standing in for a bark.
// strength scales pitch + noise brightness so DOGPARK's rapid-fire barks can read a little
// smaller/tighter than Bones' full home-screen woof.
function bark(strength=1){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    const o=AC.createOscillator(), og=AC.createGain();
    o.type="sawtooth";
    o.frequency.setValueAtTime(360*strength,t0);
    o.frequency.exponentialRampToValueAtTime(115*strength,t0+0.11);
    og.gain.setValueAtTime(0.0001,t0);
    og.gain.exponentialRampToValueAtTime(0.24,t0+0.012);
    og.gain.exponentialRampToValueAtTime(0.0001,t0+0.15);
    o.connect(og); og.connect(PRIOBUS);
    o.start(t0); o.stop(t0+0.17);
    noiseBurst(0.1, 950*strength, 0.9, 0.14, t0);
  }catch(e){}
}
/* ==================== THE SLINGSHOT, OUT LOUD ====================
   One sound per event and nothing on a timer: pick the ball up, cross the lock line, stretch a
   notch, top out, fire, bank, score, miss. They share a shape - a short pitched body with a
   little filtered noise on it - so the whole gesture reads as one object being handled. */
// taking hold of it: a soft, dry tick, nothing more
function sfxSlingGrab(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); const t0=AC.currentTime;
    noiseBurst(0.028, 900, 5, 0.045, t0);
    beep(520,.028,"square",.02,{key:"slinggrab",prio:1});
  }catch(e){}
}
// crossing out of the room and into the deck: the click of it locking into the pouch
function sfxSlingLock(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); const t0=AC.currentTime;
    noiseBurst(0.03, 2100, 3, 0.10, t0);
    beep(880,.04,"square",.045,{key:"slinglock",prio:2});
    setTimeout(()=>beep(1320,.05,"square",.04,{key:"slinglock2",prio:2}),42);
  }catch(e){}
}
/* THE BAND UNDER LOAD. One tick per notch of NEW stretch, climbing in pitch as it tightens, so
   the pull tells you how much you have without a number on screen. beep()'s own coalescing keeps
   a fast draw from turning into a machine gun. */
function slingCreak(k){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    noiseBurst(0.030, 420+k*1500, 7+k*9, 0.030+k*0.045, t0);
    beep(240+k*760,.028,"square",.016+k*0.020,{key:"slingcreak",prio:1});
  }catch(e){}
}
// held at full tension it is never silent: rubber settling, slow and dry
function slingTick(k){
  if(!SETTINGS.sound) return;
  try{ audioInit(); noiseBurst(0.022, 620+k*900, 9, 0.020+k*0.030, AC.currentTime); }catch(e){}
}
// ...and at the very top of the draw, once: a taut shimmer that says there is no more to take
function sfxSlingMax(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); const t0=AC.currentTime;
    for(let i=0;i<3;i++){
      const o=AC.createOscillator(), g=AC.createGain();
      o.type="triangle"; o.frequency.setValueAtTime(1750+i*430,t0+i*0.028);
      g.gain.setValueAtTime(0.0001,t0+i*0.028);
      g.gain.exponentialRampToValueAtTime(0.035,t0+i*0.028+0.006);
      g.gain.exponentialRampToValueAtTime(0.0001,t0+i*0.028+0.09);
      o.connect(g); g.connect(PRIOBUS); o.start(t0+i*0.028); o.stop(t0+i*0.028+0.11);
    }
  }catch(e){}
}
// the release: a fat pop with a short whoosh riding out behind it
function slingSnap(k){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    // the pop - a squat sine thump, pitched by how hard it was drawn
    const o=AC.createOscillator(), g=AC.createGain();
    o.type="sine";
    o.frequency.setValueAtTime(360+k*520,t0);
    o.frequency.exponentialRampToValueAtTime(90,t0+0.085);
    g.gain.setValueAtTime(0.0001,t0);
    g.gain.exponentialRampToValueAtTime(0.16+k*0.14,t0+0.005);
    g.gain.exponentialRampToValueAtTime(0.0001,t0+0.12);
    o.connect(g); g.connect(PRIOBUS); o.start(t0); o.stop(t0+0.14);
    // ...and the whoosh: filtered noise sweeping down as it leaves
    const dur=0.16+k*0.10;
    const buf=AC.createBuffer(1,Math.max(1,Math.floor(AC.sampleRate*dur)),AC.sampleRate);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*(1-i/d.length);
    const src=AC.createBufferSource(); src.buffer=buf;
    const f=AC.createBiquadFilter(); f.type="bandpass"; f.Q.value=1.6;
    f.frequency.setValueAtTime(2400+k*2200,t0);
    f.frequency.exponentialRampToValueAtTime(420,t0+dur);
    const wg=AC.createGain();
    wg.gain.setValueAtTime(0.10+k*0.10,t0);
    wg.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
    src.connect(f); f.connect(wg); wg.connect(PRIOBUS); src.start(t0);
  }catch(e){}
}
// put back down without a shot: the band going slack
function slingSlack(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); noiseBurst(0.05, 260, 3, 0.05, AC.currentTime); }catch(e){}
}
// off a side wall: a hard, short click, so a bank is audible even when you are watching the dog
function sfxSlingBank(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); const t0=AC.currentTime;
    noiseBurst(0.026, 2600, 2.2, 0.11, t0);
    beep(1180,.03,"square",.035,{key:"slingbank",prio:2});
  }catch(e){}
}
// on the mark: a brighter pop and three notes of a fanfare
function sfxSlingHit(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); const t0=AC.currentTime;
    noiseBurst(0.04, 3000, 1.4, 0.10, t0);
    [0,90,175].forEach((ms,i)=>setTimeout(()=>
      beep([784,988,1319][i],.075,"square",.05,{key:"slinghit"+i,prio:2}),ms));
  }catch(e){}
}
// ...and off it: a dull thud with no pitch worth hearing
function sfxSlingMiss(){
  if(!SETTINGS.sound) return;
  try{ audioInit(); const t0=AC.currentTime;
    noiseBurst(0.09, 180, 1.2, 0.09, t0);
    beep(130,.10,"sine",.035,{key:"slingmiss",prio:1});
  }catch(e){}
}
function sfxLevelUp(){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    const notes=[523.25,659.25,783.99,1046.5];   // C5 E5 G5 C6 — a clean major fanfare
    notes.forEach((f,i)=>{
      const t=t0+i*0.09, last=i===notes.length-1;
      const o=AC.createOscillator(), g=AC.createGain();
      o.type = last ? "triangle" : "square";
      o.frequency.value=f;
      g.gain.setValueAtTime(0.0001,t);
      g.gain.exponentialRampToValueAtTime(0.09,t+0.015);
      g.gain.exponentialRampToValueAtTime(0.0001,t+(last?0.35:0.13));
      o.connect(g); g.connect(PRIOBUS);
      o.start(t); o.stop(t+(last?0.38:0.16));
    });
  }catch(e){}
}
function sfxSick(){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    const o=AC.createOscillator(), g=AC.createGain();
    o.type="sawtooth";
    o.frequency.setValueAtTime(220,t0);
    o.frequency.exponentialRampToValueAtTime(70,t0+0.55);
    g.gain.setValueAtTime(0.0001,t0);
    g.gain.exponentialRampToValueAtTime(0.1,t0+0.05);
    g.gain.exponentialRampToValueAtTime(0.0001,t0+0.6);
    o.connect(g); g.connect(PRIOBUS);
    o.start(t0); o.stop(t0+0.62);
  }catch(e){}
}
function sfxBetter(){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    [520,700,900].forEach((f,i)=>{
      const t=t0+i*0.07;
      const o=AC.createOscillator(), g=AC.createGain();
      o.type="triangle"; o.frequency.value=f;
      g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.08,t+0.01); g.gain.exponentialRampToValueAtTime(0.0001,t+0.14);
      o.connect(g); g.connect(PRIOBUS); o.start(t); o.stop(t+0.16);
    });
  }catch(e){}
}
// the one moment in the whole game that should feel heaviest — a slow, solemn descent instead
// of the usual bright arcade beeps
function sfxGoodbye(){
  if(!SETTINGS.sound) return;
  try{
    audioInit();
    const t0=AC.currentTime;
    const notes=[392,349.23,293.66,261.63];   // G4 F4 D4 C4 — a slow, solemn descent
    notes.forEach((f,i)=>{
      const t=t0+i*0.55;
      const o=AC.createOscillator(), g=AC.createGain();
      o.type="sine"; o.frequency.value=f;
      g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.1,t+0.08); g.gain.exponentialRampToValueAtTime(0.0001,t+0.9);
      o.connect(g); g.connect(PRIOBUS); o.start(t); o.stop(t+0.95);
    });
  }catch(e){}
}
function haptic(pattern){
  try{ if(navigator.vibrate) navigator.vibrate(pattern); }catch(e){}
}
/* ---------- background music: a small looping chiptune bed, purely procedural ---------- */
const MUSIC_BASS=[110,110,98,110, 87.31,87.31,98,110];        // A2 A2 G2 A2 F2 F2 G2 A2
const MUSIC_ARP=[220,277.18,329.63,440];                       // A3 C#4 E4 A4
const MUSIC_BEAT=380;                  // ms per step — the title sequence lands its letters on this
let musicTimer=null, musicStep=0;
// 0..1, scaled into every note this melody plays. The title sequence brings it up from silence;
// it lives here rather than on MUSICBUS so it can never collide with sfxDuck's own gain schedule.
let MUSIC_FADE=1;
function musicTick(){
  if(!SETTINGS.music || !SETTINGS.sound) return;
  if(MUSIC_FADE<=0.001) { musicStep++; return; }
  try{
    audioInit();
    const t0=AC.currentTime;
    const bo=AC.createOscillator(), bg=AC.createGain();
    bo.type="triangle"; bo.frequency.value=MUSIC_BASS[musicStep%MUSIC_BASS.length];
    bg.gain.setValueAtTime(0.0001,t0); bg.gain.exponentialRampToValueAtTime(0.05*MUSIC_FADE,t0+0.02); bg.gain.exponentialRampToValueAtTime(0.0001,t0+0.34);
    bo.connect(bg); bg.connect(MUSICBUS); bo.start(t0); bo.stop(t0+0.36);

    const ao=AC.createOscillator(), ag=AC.createGain();
    ao.type="square"; ao.frequency.value=MUSIC_ARP[musicStep%MUSIC_ARP.length];
    ag.gain.setValueAtTime(0.0001,t0); ag.gain.exponentialRampToValueAtTime(0.022*MUSIC_FADE,t0+0.01); ag.gain.exponentialRampToValueAtTime(0.0001,t0+0.16);
    ao.connect(ag); ag.connect(MUSICBUS); ao.start(t0); ao.stop(t0+0.18);

    musicStep++;
  }catch(e){}
}
function fadeMelodyIn(ms){
  MUSIC_FADE=0;
  const steps=Math.max(1,Math.round(ms/60)); let i=0;
  const id=setInterval(()=>{ i++; MUSIC_FADE=Math.min(1,i/steps); if(i>=steps) clearInterval(id); },60);
}
function startMusic(){ if(!musicTimer) musicTimer=setInterval(musicTick,MUSIC_BEAT); }
function stopMusic(){ if(musicTimer){ clearInterval(musicTimer); musicTimer=null; } }

/* ---------- DOGCAM ambient loop: a real track for when things are good ----------
   The procedural bed above is the fallback for everywhere a mood-specific track doesn't exist
   yet (bad mood/sick — still planned). Two real ones exist now: a relaxed chiptune loop for
   hanging out with BONES on the home screen while he's actually doing well, and a driving one
   for DOGPARK runs. */
/* WOLFIE's theme. Same treatment as the other two: MP3 CBR 64k / 44.1k joint stereo, which
   is what MUSIC_GOODMOOD and MUSIC_DOGPARK already are. Trimmed to its own edges (the source had
   1.4s of dead air on the tail, which is a hole in the loop), lowpassed at 15k to strip the HE-AAC
   fizz the source carried above the band LAME keeps at this rate, and lifted +6.1dB so it sits
   with DOGPARK rather than 6dB under it. Peaks at -1.4dB, so unlike DOGPARK it never clips. */
/* MUSIC_BOSS: EMPTIED ON PURPOSE. Three base64 MP3s were ten of this file's eleven
   megabytes, and every edit-rebuild-test cycle paid for all of them. Every player
   here is guarded by its own hasTrack flag, so an empty string is a supported state
   rather than a hole - the music button and the settings toggle simply have nothing
   to play. Paste the data: URI back into this one line to restore it. */
const TRACK_VOL=0.42;
/* An element with no payload must never be handed the room: trackHas gates every context, and
   syncMoodMusic below leaves a track-less context SILENT rather than letting the procedural melody
   rush in - that bed belongs to the title and the dog selection, and hearing it over a run is
   exactly what the muffle work further down exists to prevent. */
function trackHas(a){ return !!(a && a.hasTrack); }
const MOOD_AUDIO = new Audio();
MOOD_AUDIO.hasTrack=!!MUSIC_GOODMOOD; if(MOOD_AUDIO.hasTrack) MOOD_AUDIO.src=MUSIC_GOODMOOD;
MOOD_AUDIO.loop = true; MOOD_AUDIO.volume = TRACK_VOL; MOOD_AUDIO.preload = "auto";
let moodMusicOn = false;
const MOOD_AUDIO_PARK = new Audio();
MOOD_AUDIO_PARK.hasTrack=!!MUSIC_DOGPARK; if(MOOD_AUDIO_PARK.hasTrack) MOOD_AUDIO_PARK.src=MUSIC_DOGPARK;
MOOD_AUDIO_PARK.loop = true; MOOD_AUDIO_PARK.volume = TRACK_VOL; MOOD_AUDIO_PARK.preload = "auto";
let parkMusicOn = false;
const BOSS_AUDIO = new Audio();
BOSS_AUDIO.hasTrack=!!MUSIC_BOSS; if(BOSS_AUDIO.hasTrack) BOSS_AUDIO.src=MUSIC_BOSS;
BOSS_AUDIO.loop = true; BOSS_AUDIO.volume = TRACK_VOL; BOSS_AUDIO.preload = "auto";
let bossMusicOn = false;
/* Cross-context switches used to cut a track dead the instant MODE changed, so leaving DOGCAM for
   a run clipped one loop off mid-bar while the next one started underneath it. Every start/stop
   below goes through these instead: the outgoing track rides its volume down and only then pauses,
   the incoming one comes up from silence, and each track owns a single timer so a fast
   back-and-forth (home -> park -> home) can never leave two fades fighting over the same element. */
const AUDIO_FADES=new WeakMap();
function fadeAudio(a, to, ms, thenPause){
  clearInterval(AUDIO_FADES.get(a));
  const from=a.volume, steps=Math.max(1,Math.round(ms/40));
  let i=0;
  const id=setInterval(()=>{
    i++;
    a.volume=clamp(from+(to-from)*(i/steps),0,1);
    if(i>=steps){
      clearInterval(id); AUDIO_FADES.delete(a);
      if(thenPause){ a.pause(); a.volume=TRACK_VOL; }
    }
  },40);
  AUDIO_FADES.set(a,id);
}
/* play() resolves a frame or two late, which is long enough for a fast context switch (closing
   Settings straight into a park run) to have already asked this same track to fade out. Without a
   token the stale resolve would cancel that fade-out and pull the track back up — two tracks
   playing at once, which is the exact thing the fades exist to prevent. Every start/stop takes a
   fresh token, and a resolve holding a stale one does nothing. */
const AUDIO_GEN=new WeakMap();
function bumpGen(a){ const g=(AUDIO_GEN.get(a)||0)+1; AUDIO_GEN.set(a,g); return g; }
function trackIn(a){
  clearInterval(AUDIO_FADES.get(a)); AUDIO_FADES.delete(a);
  const gen=bumpGen(a);
  a.volume=0;
  a.play().then(()=>{
    if(AUDIO_GEN.get(a)!==gen) return;    // something else took the room while we were starting
    fadeAudio(a,TRACK_VOL,420,false);
  }).catch(()=>{ if(AUDIO_GEN.get(a)===gen) a.volume=TRACK_VOL; });
}
function trackOut(a){ bumpGen(a); fadeAudio(a,0,320,true); }
/* MUFFLE — what a panel does to the music underneath it.
   Opening the wave shop used to swap the park track out for the little procedural menu melody,
   which threw away the run's momentum every single wave. It now keeps playing and simply moves
   behind a door: two cascaded lowpasses (12dB/oct each — one alone is too gentle to read as
   anything but "quieter") plus a gain duck.
   The element has to be routed through the AudioContext for that, and createMediaElementSource
   both permanently reroutes an element and silences its direct output — so it is done lazily, on
   the first muffle, and only while AC is actually running. If there is no context to route
   through, the music just keeps playing unfiltered: the important half of this (not swapping
   tracks) still holds, and nothing can end up silent for the sake of an effect. */
const MUFFLE=new WeakMap();
const MUFFLE_HZ=520, MUFFLE_GAIN=0.62, MUFFLE_OPEN=18000;
function muffleGraph(a){
  let m=MUFFLE.get(a);
  if(m!==undefined) return m;
  if(!AC || AC.state!=="running") return null;                // not cached: retry when it is
  try{
    const src=AC.createMediaElementSource(a);
    const lp1=AC.createBiquadFilter(), lp2=AC.createBiquadFilter();
    lp1.type=lp2.type="lowpass"; lp1.Q.value=lp2.Q.value=0.7;
    lp1.frequency.value=lp2.frequency.value=MUFFLE_OPEN;
    const g=AC.createGain(); g.gain.value=1;
    // straight out, NOT via MUSICBUS/MASTER. An unrouted <audio> element already bypasses both,
    // so going through them here would quietly sign the music up for sfxDuck and the master
    // limiter the first time a shop opened — a mix change nobody asked for, halfway through a run.
    src.connect(lp1); lp1.connect(lp2); lp2.connect(g); g.connect(AC.destination);
    m={lp1,lp2,g}; MUFFLE.set(a,m); return m;
  }catch(e){ MUFFLE.set(a,null); return null; }               // already routed elsewhere: give up for good
}
function setMuffle(a,on){
  const m=muffleGraph(a);
  if(!m) return;
  const t=AC.currentTime, tc=0.07;
  for(const f of [m.lp1.frequency, m.lp2.frequency]){
    f.cancelScheduledValues(t); f.setTargetAtTime(on?MUFFLE_HZ:MUFFLE_OPEN, t, tc);
  }
  m.g.gain.cancelScheduledValues(t);
  m.g.gain.setTargetAtTime(on?MUFFLE_GAIN:1, t, tc);
}
/* Which panels muffle the run rather than replace it: the ones that are part of the run itself.
   #settingsPanel is deliberately NOT one of them — it is the same global menu the home screen
   opens, and it keeps the menu melody it has always had. */
function parkPanelOverRun(){
  return !!(typeof PK!=="undefined" && PK.active &&
            (PK.shop||PK.convertOpen||PK.friendsOpen||PK.gateAsk||PK.endRunAsk));
}
/* Cheap enough to call every frame, and only touches the graph when the answer actually changes.
   parkMusicOn is tested FIRST and that order matters: boot calls syncMoodMusic() before `const PK`
   further down the file has initialised, and `typeof PK` does NOT save you inside a const's
   temporal dead zone — it throws, which aborts the rest of the script. parkMusicOn is a plain
   early `let`, and it cannot be true before there is a park to play for. */
let muffleOn=false;
function syncMusicMuffle(){
  const want = parkMusicOn && parkPanelOverRun();
  if(want===muffleOn) return;
  muffleOn=want;
  setMuffle(MOOD_AUDIO_PARK, want);
}
function pkGoodMoodMusic(){ return MODE==="home" && !S.sick && dogMoodState()!=="sad"; }
// the boss OWNS the room from the first frame of its arrival, but does not SING until the floor
// has already broken — the rumble plays against nothing, which is the whole point of it
function pkBossHasRoom(){ return MODE==="park" && PK.active && PK.boss && PK.boss.active; }
function pkBossMusic(){ return pkBossHasRoom() && !(BOSS.ph==="intro" && BOSS.introT<BOSS_MUSIC_AT); }
function pkParkMoodMusic(){ return MODE==="park" && PK.active && !pkBossHasRoom(); }
/* The little procedural melody is the game's front-of-house theme: it owns every screen that
   isn't the world itself — the title/adoption sequence on first load, the settings panel, and
   any panel that has the world paused underneath it. Stepping into DOGCAM or a park run hands
   over to that context's own chiptune track, and stepping back out hands it straight back. */
function menuMusicWanted(){
  if($("#start") && $("#start").offsetParent) return true;          // title + adoption sequence
  if($("#settingsPanel") && $("#settingsPanel").classList.contains("show")) return true;
  if($("#mystPanel") && $("#mystPanel").classList.contains("show")) return true;
  // A panel that belongs to a live run no longer takes the music with it — the run's own track
  // keeps playing, muffled (see setMuffle). Settings is the exception: it is the global menu.
  if(typeof PK!=="undefined" && PK.active && PK.settingsOpen) return true;
  return false;
}
// idempotent by design — always computes the state every music system should be in right now,
// rather than only acting on a change, so it's safe to call from anywhere (boot, a screen
// switch, the settings toggle, or just the periodic meter refresh) with no ordering assumptions.
// The three contexts are mutually exclusive, so at most one of them ever wants to be playing.
function syncMoodMusic(){
  const base = SETTINGS.music && SETTINGS.sound && !document.hidden;
  const wantMenu = base && menuMusicWanted();
  /* ctx = "this context owns the room"; want = "...and it has a track to fill it with". The two
     are separate so a context whose track has been removed still SILENCES the procedural bed. */
  const homeCtx = base && !wantMenu && pkGoodMoodMusic();
  const bossCtx = base && !wantMenu && pkBossMusic();
  const parkCtx = base && !wantMenu && pkParkMoodMusic();
  const wantHome = homeCtx && trackHas(MOOD_AUDIO);
  const wantBoss = bossCtx && trackHas(BOSS_AUDIO);
  const wantPark = parkCtx && trackHas(MOOD_AUDIO_PARK);
  if(wantHome){
    if(!moodMusicOn){ moodMusicOn=true; stopMusic(); trackIn(MOOD_AUDIO); }
  } else if(moodMusicOn){ moodMusicOn=false; trackOut(MOOD_AUDIO); }
  if(wantPark){
    if(!parkMusicOn){ parkMusicOn=true; stopMusic(); trackIn(MOOD_AUDIO_PARK); }
  } else if(parkMusicOn){
    parkMusicOn=false; trackOut(MOOD_AUDIO_PARK);
    if(muffleOn){ muffleOn=false; setMuffle(MOOD_AUDIO_PARK,false); }   // never hand it back filtered
  }
  if(wantBoss){
    if(!bossMusicOn){ bossMusicOn=true; stopMusic(); trackIn(BOSS_AUDIO); }
  } else if(bossMusicOn){ bossMusicOn=false; trackOut(BOSS_AUDIO); }
  if(!wantHome && !wantPark && !wantBoss){
    // ...and the little procedural melody must NOT rush in to fill that silence
    if(base && !pkBossHasRoom() && !homeCtx && !parkCtx && !bossCtx) startMusic(); else stopMusic();
  }
  syncMusicMuffle();
}
// The AudioContext boots suspended until the page has seen a real gesture, so the title melody
// can't actually sound on a cold load however early it's asked to. This catches the very first
// interaction anywhere, wakes the context, and re-runs the sync so whatever should be playing
// by then starts for real.
(function(){
  const wake=()=>{
    try{ audioInit(); if(AC.state==="suspended") AC.resume(); }catch(e){}
    syncMoodMusic();
  };
  for(const ev of ["pointerdown","keydown","touchstart"]) window.addEventListener(ev,wake,{once:true});
})();

/* ---------- toast -> THE DOGGIE LOG ---------- */
// Notices used to flash past on a strip over the dog, which meant anything you didn't happen to
// be looking at was simply gone. They now land in the DOGGIE LOG at the top of the controls: the
// newest one sits there to be read at leisure, and tapping it opens the last ten. The floating
// toast is still the fallback for the two places the controls aren't ours to use: the title
// screen (no control panel yet) and a live park run (the park owns the whole screen).
let toastT=0;
const DOGLOG=[], DOGLOG_KEEP=10;
function toast(msg,red){
  msg=DN(msg);
  if(PARK_HDR || $("#game").classList.contains("hidden")){
    const t=$("#toast"); t.textContent=msg; t.className=red?"red":"";
    t.style.display="block"; clearTimeout(toastT);
    toastT=setTimeout(()=>t.style.display="none",1700);
    return;
  }
  dogLog(msg,red);
}
// one entry. Repeats collapse into a counter rather than filling the whole log with the same line.
function dogLog(msg,red){
  const when="DAY "+CLK.day+" "+String(Math.floor(CLK.h)).padStart(2,"0")+":00";
  const top=DOGLOG[0];
  if(top && top.msg===msg){ top.n++; top.when=when; top.red=!!red; }
  else {
    DOGLOG.unshift({msg, red:!!red, when, n:1});
    while(DOGLOG.length>DOGLOG_KEEP) DOGLOG.pop();
  }
  renderDogLog(true);
  if($("#dlogPanel").classList.contains("show")) renderDogLogList();
}
function renderDogLog(fresh){
  const btn=$("#dlogMsg"); if(!btn) return;
  const e=DOGLOG[0];
  btn.textContent = e ? (e.msg + (e.n>1 ? " (x"+e.n+")" : "")) : "A QUIET DAY SO FAR.";
  const box=$("#doggieLog");
  box.classList.toggle("red", !!(e && e.red));
  $("#dlogMore").textContent = DOGLOG.length>1 ? "\u25B2 "+DOGLOG.length : "\u25B2";
  const pip=$("#dlogPts"), n=S.pts||0;
  pip.textContent="+"+n; pip.classList.toggle("hidden", n<=0);
  if(fresh && !SETTINGS.reduceMotion){       // a short flicker on the border, nothing that moves
    box.classList.remove("fresh"); void box.offsetWidth; box.classList.add("fresh");
  }
}
function renderDogLogList(){
  const list=$("#dlogList");
  list.innerHTML = DOGLOG.length
    ? DOGLOG.map((e,i)=>'<div class="prow"'+(e.red?' style="border-color:#f22"':'')+
        '><span class="nm"'+(e.red?' style="color:#f22"':'')+'>'+
        (i===0?'<span class="dlNew">\u25B8 </span>':'')+e.msg+(e.n>1?' (x'+e.n+')':'')+
        '<br><span class="dlWhen">'+e.when+'</span></span></div>').join("")
    : '<div class="tiny" style="color:#555;padding:6px 0">NOTHING LOGGED YET.</div>';
}
$("#doggieLog").onclick=()=>{ openDogLog(); };
function openDogLog(){ renderDogLogList(); renderDogLogStats(); $("#dlogPanel").classList.add("show"); beep(500,.05); }
/* The three-way assignment. Reached two ways — it opens itself on a level-up when nothing else
   is on screen, and it is always available from the log for points that banked instead. */
function openSkillPanel(){
  /* IT OPENS WITH NOTHING TO SPEND. The tree is the map of what this dog can become, and refusing
     to show it until a point happens to be in hand made it a receipt rather than a plan. Nothing
     in here can be bought without a point - learnTrick still checks - so there is nothing to
     protect against.
     Open on the cheapest thing he could actually learn right now, so the readout underneath is
     never blank and the first thing you read is a live option rather than an instruction. */
  const next=TRICKS.find(t=>!hasTrick(t.k) && !t.soon && (!t.req||hasTrick(t.req)) && (S.pts||0)>=t.cost);
  TREESEL=null; treeSelect(next ? next.k : "bond");
  renderSkillPanel();
  $("#skillPanel").classList.add("show");
  beep(660,.07); setTimeout(()=>beep(880,.09),90);
}
function attrBarHTML(k, big){
  const v=S[k]||0, over=attrOver(k);
  const base=clamp(Math.min(v,ATTR_FULL),0,ATTR_FULL);
  // the bar is the 0-100 track; overfill rides on top as its own bright segment past the end
  return '<div class="abar'+(big?" big":"")+(over>0?" over":"")+'">'+
    '<i style="width:'+base+'%"></i>'+
    (over>0?'<u style="width:'+(over/(ATTR_CAP-ATTR_FULL)*100)+'%"></u>':'')+
    '</div>';
}
function attrRowsHTML(big){
  return ATTRS.map(([lb,k])=>{
    const v=S[k]||0, over=attrOver(k);
    return '<div class="arow"><span class="alb">'+lb+'</span>'+attrBarHTML(k,big)+
      '<span class="aval'+(over>0?" over":"")+'">'+Math.round(v)+'</span></div>';
  }).join("");
}
function renderSkillPanel(){
  const n=S.pts||0;
  $("#skillPts").textContent = n+" SKILL POINT"+(n===1?"":"S");
  if(TREESEL) treeSelect(TREESEL);
  $("#skillRows").innerHTML = ATTRS.map(([lb,k])=>{
    const v=S[k]||0, full=v>=ATTR_FULL, capped=v>=ATTR_CAP;
    return '<button class="skillRow'+(capped?" locked":"")+'" data-attr="'+k+'"'+(capped?" disabled":"")+'>'+
      '<span class="alb">'+lb+'</span>'+attrBarHTML(k,true)+
      '<span class="aval'+(attrOver(k)>0?" over":"")+'">'+Math.round(v)+'</span>'+
      '<span class="afx">'+(capped?"AT THE CEILING":full?"PUSH PAST FULL \u2014 IT WILL SETTLE":ATTR_NOTE[k])+'</span></button>';
  }).join("");
}
$("#skillRows").addEventListener("click",e=>{
  const b=e.target.closest("button[data-attr]");
  if(!b||b.disabled) return;
  spendSkillPoint(b.dataset.attr);
});

$("#skillLater").onclick=()=>{ $("#skillPanel").classList.remove("show"); beep(400,.05); renderDogLog(false); };
/* The same exit, pinned to the top of the panel. LATER sits at the end of a scrolling column now,
   which is fine on the phone it was designed on and off the bottom of the screen on a taller one -
   and a panel whose only exit you have to know to scroll for is a panel you are trapped in. */
$("#skillClose").onclick=()=>$("#skillLater").click();
$("#gooutClose").onclick=()=>$("#goClose").click();
// the log is where the stats live: what he needs right now, and what he has become
function renderDogLogStats(){
  const el=$("#dlogStats"); if(!el) return;
  const needs=[["HUN","hunger"],["THI","thirst"],["ENE","energy"],["CLN","clean"],["FUN","fun"],["MOO","mood"]];
  el.innerHTML =
    '<div class="dlSect">RIGHT NOW</div>'+
    '<div class="needGrid">'+needs.map(([lb,k])=>{
      const v=clamp(Number(S[k])||0,0,100);
      return '<div class="nrow"><span class="nlb">'+lb+'</span><div class="bar'+(v<25?" crit":"")+'"><i style="width:'+v+'%"></i></div></div>';
    }).join("")+'</div>'+
    '<div class="dlSect gold">TRAINING \u2014 LV.'+S.lvl+'</div>'+
    '<div class="attrGrid">'+attrRowsHTML(false)+'</div>'+
    ((S.pts||0)>0
      ? '<button id="dlogSpend" class="skillCta">\u25B2 SPEND '+S.pts+' SKILL POINT'+(S.pts===1?"":"S")+'</button>'
      : '<div class="dlHint">'+(anyOverfill()?"OVERFILLED \u2014 IT IS BLEEDING BACK TO FULL":"NEXT SKILL POINT AT LV."+(S.lvl+1))+'</div>');
  const sp=$("#dlogSpend");
  if(sp) sp.onclick=()=>{ $("#dlogPanel").classList.remove("show"); openSkillPanel(); };
}
$("#dlogClose").onclick=()=>$("#dlogPanel").classList.remove("show");

/* ---------- state ---------- */
const S = {
  /* THE WINDOW TAKES DAMAGE NOW. Three hits from the ball and it goes: one crack, two, then the
     glass is out of it. A broken window is a hole into the room at night, and things come in. */
  winCracks:0, winBroken:false, vampire:false,
  /* ...but cracked glass MENDS. Seconds since the last impact: ten of them and the pane starts
     knitting, ten more and it is clear again. So three hits is still what takes the window out —
     it just has to be three hits inside the same twenty-second window, which turns "the window
     broke at some point this week" into a thing you can actually see yourself doing. */
  winHealT:0,
  /* ...AND THE ANSWER TO IT, which is a set of shutters. tier 1 blinds cut the shaft; tier 2
     blackout lining seals the frame well enough that a broken pane stops being an invitation.
     These live on S, so snapshot() (which serialises S whole) already saves them. */
  blindsOwned:false, blindsShut:false, blindsTier:0,
  dogName:"BONES", sel:"bones",
  pup:{owned:false,name:"",hunger:70,thirst:70,mood:75,xp:0,lvl:1},
  pFeed:false, pPlay:false, pPet:false,
  hunger:52, thirst:48, energy:80, clean:80, fun:70, mood:70, groom:90,
  money:10, earned:0, petCd:0,
  owned:{}, equipped:null,
  dailyUsed:false, bestDaily:0, bestPractice:0,
  streak:0, dayNeglected:false, sick:false, sickTimer:0, wellTimer:0, dead:false, neglectNight:false, neglectNights:0,
  kibble:3, snacks:2, beach:false, compsToday:0,
  mystDay:-1, mystMet:false,   // the mysterious dog: last day he showed, and whether you've met him
  jWave3:false, jCollar:false, jTrick:false,
  dHappy:false, dNour:false, dBall:false, dPark:false, dClean:false, dWater:false, dFood:false,
  hoopOwned:false, ballOwned:false, ballStock:0, ballThrows:0, brushOwned:false, shampooOwned:false, shampooPct:0, firstWater:false, firstFood:false, bedHinted:false, pbTutorialDone:false, mail:[],
  bedTier:0, tricks:{}, todoWork:false, todoLvl5:false, todoBed:false, todoPark:false, todoBall:true, todoBowls:false, twW:false, twF:false, todoHide:false, outTimer:0,
  lvl:1, xp:0, gen:1, senior:false, seniorDays:0, lifePathChosen:false, litter:false, memorialSrc:null, pendingStage:[],
  hollowBeaten:false,   // WOLFIE has been put down at least once — this is what opens burial
                      // (the save key keeps its old name; only the display name changed)
  // trained attributes — see TRAINED ATTRIBUTES. Start at 10: a puppy is not made of nothing.
  str:10, stam:10, vit:10, pts:0, trainAcc:{},
  lastSaveAt:null, lastSaveDay:0, lastSaveH:0
};
// music on by default: the title sequence is scored to the melody, so a silent first boot would
// hide the whole opening. A save that already carries an explicit preference still wins (see
// loadGame), so nobody who deliberately turned it off gets it switched back on.
const SETTINGS = { sound:true, reduceMotion:false, music:true, musicDefaultMigrated:true, barkStyle:"circle", nightMode:true, vignette:60, shake:"full" };
const CHARMS = [
  {id:"spike", name:"SPIKED COLLAR", cost:15, unlock:3,   fx:"+15% SPEED / -10% JUMP",            mod:{spd:1.15,jmp:0.90}},
  {id:"band",  name:"RED BANDANA",   cost:10, unlock:8,   fx:"+15% JUMP",                          mod:{jmp:1.15}},
  {id:"bell",  name:"BRASS BELL",    cost:12, unlock:14, fx:"OBSTACLES SPAWN FARTHER OUT",        mod:{tele:1.35}},
  {id:"bonec", name:"BONE CHARM",    cost:20, unlock:25, fx:"+25% SCORE / -8% SPEED",             mod:{scr:1.25,spd:0.92}},
  {id:"tag",   name:"STEEL TAG",     cost:18, unlock:35, fx:"+1 LIFELINE (PRACTICE ONLY)",        mod:{life:1}},
  {id:"rope",  name:"LUCKY ROPE",    cost:15, unlock:45, fx:"DAILY GATE HINT STAYS ON SCREEN",    mod:{hint:1}},
  {id:"shadow",name:"SHADOW LEASH",  cost:25, unlock:70, fx:"+25% SPEED / COURSE GOES DARK",      mod:{spd:1.25,dark:1}},
  {id:"chain", name:"CHAIN COLLAR",  cost:30, unlock:85, fx:"+10% SPD +10% JMP / MOOD DRAINS FAST",mod:{spd:1.10,jmp:1.10,moodDrain:1}}
,
  {id:"legacy",name:"LEGACY TAG", cost:0, unlock:1, fx:"+10% SPD/JMP/SCORE \u2014 INHERITED", mod:{spd:1.10,jmp:1.10,scr:1.10}}
];
function mods(){
  const m={spd:1,jmp:1,scr:1,tele:1,life:0,hint:0,dark:0,moodDrain:0};
  const c=CHARMS.find(c=>c.id===S.equipped);
  if(c) Object.assign(m,{...m,...c.mod});
  return m;
}

/* ---------- meters ---------- */
const METERS=[["HUNGER","hunger"],["THIRST","thirst"],["ENERGY","energy"],["CLEAN","clean"],["FUN","fun"],["MOOD","mood"],["GROOM","groom"]];
function buildMeters(){
  $("#meters").innerHTML = METERS.map(([lb,k])=>
    `<div class="mrow"><span class="lb">${lb}</span><div class="bar" id="bar_${k}"><i></i></div></div>`).join("");
}
$("#money1").style.cursor="pointer"; $("#money2").style.cursor="pointer"; $("#money3").style.cursor="pointer";
// set by the main loop while a park run is on screen. Declared with var, and never read
// during init, because park.js (and its `const PK`) is concatenated after this file.
var PARK_HDR=false;
function syncParkHeader(){
  $("#camlabel").textContent = PK.plusMode ? "DOGPARK UNLEASHED" : "DOGPARK";
  $("#clock").textContent    = "WAVE "+PK.wave;
  $("#camstate").textContent = pkLeftCount()+pkLeftLabel();
  $("#needAlert").classList.add("hidden");     // home needs are not the park's business
}
function restoreCamHeader(){
  $("#camlabel").innerHTML='<span class="rec">&#9679;</span> DOGCAM';
}
function renderMeters(){
  for(const [,k] of METERS){
    const el=$("#bar_"+k);
    // clamp defensively on the way to the DOM: an out-of-range or non-finite value (NaN,
    // undefined, a stray negative from somewhere) is invalid CSS and gets silently ignored by
    // the browser, leaving the bar frozen at whatever width it last had rather than reflecting
    // the real (now-fixed) stat underneath
    const v=clamp(Number(S[k])||0,0,100);
    el.classList.toggle("crit", v<25);
    el.firstElementChild.style.width = v+"%";
  }
  const sa=$("#stAttrs");
  if(sa) sa.innerHTML=attrRowsHTML(false);
  if(S.mood>=90) tickTodo("d_happy");
  if(S.pup.owned){ renderDogSel._t=(renderDogSel._t||0)+1; if(renderDogSel._t%8===0) renderDogSel();
    if((S.pup.hunger<30||S.pup.thirst<30) && Math.random()<0.05){ toast(S.pup.name+" IS WHINING \u2014 CHECK THE BOWLS",1); beep(180,.2,"sawtooth",.03); } }
  const minv=Math.min(S.hunger,S.thirst,S.energy,S.clean,S.fun,S.mood);
  const na=$("#needAlert");
  na.classList.toggle("hidden", minv>=80);
  na.classList.toggle("crit", minv<40);
  const neg=S.money<0, mstr=(neg?"-$":"$")+Math.abs(S.money);
  for(const id of ["money1","money2","money3"]){ const el=$("#"+id); if(el) el.textContent=mstr; }
  $("#money2").style.color=neg?"#f22":"#fff"; $("#money3").style.color=neg?"#f22":"#fff";
  $("#moneyRow").style.color=neg?"#f22":"#3fdc7a";
  $("#hudBones").textContent = S.snacks;   // the bone stock park runs bank into -- the icon says "bones", the label doesn't need to
  syncMoodMusic();   // cheap and idempotent — this is where a drifting mood/sickness gets noticed
  if(PARK_HDR) return;              // the park owns the header; don't stamp the clock over it
  $("#clock").textContent = "DAY "+CLK.day+" "+String(Math.floor(CLK.h)).padStart(2,"0")+":00"+(atWorkNow()?" ▶▶":"");
  $("#bests").textContent = "STREAK "+S.streak+"d";
}

/* ---------- stats sim ---------- */
// While the owner is out at a job the dogcam runs on fast-forward: the clock races, BONES
// scampers through his usual routine at speed, and his needs drain a little quicker than they
// would at home — so leaving him alone for a shift has a real cost.
const WORK_CLOCK_FF=2.5, WORK_NEED_FF=1.25;
let WORK_FF=1, NEED_FF=1;
function atWorkNow(){ return MODE==="work" || MODE==="paperboy"; }
function tickStats(dt, force){
  // The park exists outside the day. Nothing decays and the clock does not move while a run
  // is on; each cleared wave spends a flat 15 minutes instead (see parkUpdate). Without this
  // a long run burned a whole night and you came home straight into the bedtime panel.
  if(PK.active && !force) return;
  const m=mods();
  const nm=(S.senior?0.6:1)*NEED_FF;
  // AN APPETITE THAT DOES NOT KEEP. Hunger and thirst run twice as fast while he is cursed —
  // the rest of the meters are unchanged, except for what standing in the sun does to them.
  const vm=isVamp()?2:1;
  S.hunger = clamp(S.hunger - 0.18*nm*vm*dt, 0, 100);
  S.thirst = clamp(S.thirst - 0.30*nm*vm*dt, 0, 100);
  S.clean  = clamp(S.clean  - 0.09*nm*dt, 0, 100);
  S.groom  = clamp(S.groom  - 0.012*nm*dt, 0, 100);   // coat matts far slower than anything else
  S.fun    = clamp(S.fun    - 0.15*nm*dt, 0, 100);
  const resting = CAM.state==="rest" || CAM.state==="bedsleep";
  /* A nap in a bed that actually fits him is the single best thing he can be doing: it fills him
     back up nearly twice as fast as dozing anywhere else, and it settles him while he's there.
     Without a bed, or in one he has outgrown, the old rate and the 70% ceiling both stand. */
  const goodBed = resting && bedAdequate();
  const energyCap = resting ? (bedAdequate()?100:70) : 100;
  const restMul=1+0.5*attrF1("stam");   // STAMINA — a fit dog gets more out of the same nap
  const restRate = goodBed ? 4.4 : 2.4;
  S.energy = clamp(S.energy + (resting?restRate*restMul:(MODE==="home"?0.10*restMul:-0.02*NEED_FF))*dt, 0, energyCap);
  /* NO DAYTIME PENALTY. This used to drain him through daylight hours to push him toward a midday
     nap - and the nap is gone, so the thing that motivated it goes with it. He tires and rests
     exactly like any other dog now; the difference is that nothing MAKES him. */
  if(goodBed) S.fun = clamp(S.fun + 0.22*dt, 0, 100);      // curled up somewhere of his own
  const target=(S.hunger+S.thirst+S.energy+S.clean+S.fun)/5;
  S.mood = clamp(S.mood + (target-S.mood)*0.05*dt - (m.moodDrain?0.15*dt:0), 0, 100);
  if(goodBed) S.mood = clamp(S.mood + 0.30*dt, 0, 100);    // ...and content the whole time
  if(MOOD_BOOST_T>0){ MOOD_BOOST_T=Math.max(0,MOOD_BOOST_T-dt); S.mood=100; }
  S.petCd = Math.max(0, S.petCd-dt);
  S.outTimer += dt;
  if(S.clean<70) SPONGE.rew=false;
  if(S.groom<70) BRUSH.rew=false;
  if(POOS.length){ S.mood=clamp(S.mood-0.025*POOS.length*dt,0,100); S.clean=clamp(S.clean-0.01*POOS.length*dt,0,100); }
  if(S.outTimer>150 && POOS.length<3 && !R.active && !OUTING.active){
    S.outTimer=40;
    // right by his bed, in FLOOR coordinates - the old version stored a canvas fraction taken
    // off a bed rect that had not been where the bed was for three versions
    POOS.push({x:clamp(SPOT.bed.x+(Math.random()-0.5)*0.22,0.06,0.94), z:SPOT.bed.z+0.06});
    toast("BONES POOPED INDOORS \u2014 TAP TO PICK UP",1); beep(160,.15,"sawtooth",.03);
  }
  // 24h game clock: 10 real seconds = 1 game hour (1 day = 4 min)
  // sickness: sustained severe neglect makes him properly ill
  /* NOTHING SO ORDINARY AS ILLNESS. Whatever came through the window took that off the table, so
     the sick clock does not run at all while he is cursed - and any illness he already had is
     cleared, rather than waiting frozen for the cure to hand it back to him. */
  if(isVamp()){
    S.sick=false; S.sickTimer=0; S.wellTimer=0;
  } else {
    if(avgStat()<20){ S.sickTimer+=dt; S.wellTimer=0; } else { S.wellTimer+=dt; }
    if(!S.sick && S.sickTimer>75){ S.sick=true; toast("BONES IS SICK. HE NEEDS CARE \u2014 NO RUNS UNTIL HE RECOVERS.",1); sfxSick(); haptic([50,60,50]); }
    if(S.sick && S.wellTimer>25){ S.sick=false; S.sickTimer=0; S.dead=false; toast("BONES IS FEELING BETTER."); sfxBetter(); }
  }
  if(avgStat()<25) S.dayNeglected=true;
  /* THE UNDEAD DO NOT GO TO BED. A vampire was given his own bedtime at midday, which was a
     smaller version of the same wrong idea: the thing that makes no sense is not WHEN he sleeps,
     it is that something still marches him off to bed at all. Nothing raises the panel on him now
     - not midnight, not midday. He may still choose to nap (the bed is his, toggleRest still
     works); he is simply never sent. */
  CLK.h += dt*WORK_FF/10;
  if(CLK.h>=24){
    CLK.h-=24; CLK.day++;
    if(!isVamp()) SLEEP.pending=true;
    if(!S.dayNeglected){
      S.streak++; S.money+=5; addXP(25);
      toast("GOOD CARE STREAK: "+S.streak+" DAY"+(S.streak>1?"S":"")+" \u2014 +$5"); beep(760,.08); setTimeout(()=>beep(980,.08),100);
    } else {
      if(S.streak>0) toast("STREAK BROKEN \u2014 BONES WAS NEGLECTED");
      S.streak=0;
      addMail("neglect","A ROUGH NIGHT", NAME().toUpperCase()+" WAS NEGLECTED OVERNIGHT \u2014 HIS CARE NEEDS ATTENTION TODAY.");
    }
    S.dayNeglected=false;
    S.compsToday=0;
    for(const k of ["dHappy","dNour","dBall","dPark","dClean","dWater","dFood","pFeed","pPlay","pPet"]) S[k]=false;
    TODO_NEW=TODO_NEW.filter(k=>!k.startsWith("d_"));   // unclaimed daily rewards expire
    renderTodo();
    addMail("newday","A NEW DAY HAS BEGUN","FRESH TO-DOS ARE WAITING FOR "+NAME().toUpperCase()+" \u2014 CHECK THE LIST.");
    if(CLK.day-(S.lastSaveDay||0)>=2){
      addMail("save","DON'T FORGET TO SAVE","IT'S BEEN "+(CLK.day-(S.lastSaveDay||0))+" DAYS SINCE YOUR LAST SAVE \u2014 YOU COULD LOSE "+NAME().toUpperCase()+"'S PROGRESS.");
    }
    if(S.senior){ S.seniorDays++; if(S.seniorDays===5) setTimeout(startGoodbye,800); }
    if((CLK.day-1)%7===0){ // every 7 days the bills land
      const why=["RENT","BILLS","INSURANCE","VET FUND","BOILER REPAIR"][Math.floor(Math.random()*5)];
      S.money-=20;
      toast(why+" DUE \u2014 -$20"+(S.money<0?" \u2014 YOU'RE IN THE RED":""),1);
      beep(90,.3,"sawtooth");
      renderMeters(); renderShop();
    }
  }
}
// groom is deliberately excluded: it decays over days, so folding it in would slowly poison
// the sickness and neglect checks that key off this average
function avgStat(){ return (S.hunger+S.thirst+S.energy+S.clean+S.fun+S.mood)/6; }

/* ===================== TRAINED ATTRIBUTES =====================
   The middle layer the game was missing. Needs are how he feels right now; level is how far he
   has come; these are how capable he actually IS, and they do not care whether he ate this
   morning. Three of them, permanent, never decaying:

     STRENGTH  power and impact    — knockback, bark damage, blade and stomp damage
     STAMINA   endurance and pace  — speed, slower drain, shorter cooldowns
     HEALTH    resilience          — max HP, shield ceiling, armour

   Deliberately NOT part of the six need meters, and drawn in gold rather than white/red, so
   "he's weak" is never mistaken for "he's hungry".

   Two ways they grow:
     - a SKILL POINT every level, assigned by the owner. Raw +1, no diminishing returns: an
       assigned point is a decision and should always feel like one.
     - EARNED TRAINING from things he actually did (drills, a park run), which runs through
       trainGain()'s diminishing curve so grinding can never outpace the point economy, and
       which stops dead at ATTR_FULL.

   Past ATTR_FULL is OVERFILL: only a spent point can push there, effects scale at double rate,
   and it bleeds back down to full on its own. An hour of absurdity bought with a real resource. */
const ATTRS=[["STRENGTH","str"],["STAMINA","stam"],["HEALTH","vit"]];
const ATTR_NOTE={str:"POWER — KNOCKBACK, BARK & BLADE DAMAGE",
                 stam:"ENDURANCE — SPEED, DRAIN, COOLDOWNS",
                 vit:"RESILIENCE — MAX HP, SHIELD, ARMOUR"};
const ATTR_START=10, ATTR_FULL=100, ATTR_CAP=150;
const ATTR_DRAIN_SEC=20;        // real seconds per point of overfill bled off — a 150 lasts ~17min
// full gain below 40, half 40-70, quarter above — training never stops paying, it just slows
function trainGain(current, raw){
  const mul = current < 40 ? 1 : current < 70 ? 0.5 : 0.25;
  return raw * mul;
}
// a tired, miserable dog trains badly. Care still matters; training never replaces it.
function trainEfficiency(){ return 0.45 + 0.55*clamp((S.energy+S.mood)/200,0,1); }
// 0 at nothing, 1.0 at full, 2.0 at the overfill cap — every effect below reads this one number
function attrF(k){
  /* THE CURSE IS READ, NEVER WRITTEN. A vampire is at full strength and stamina, and this is the
     one place to say so: writing 100 into S.str/S.stam would erase whatever he had actually
     trained, and curing him would hand back a dog with somebody else's numbers. Read-time means
     the training sits untouched on disk the whole time and comes straight back. Vitality is
     deliberately NOT included - the curse makes him strong, not harder to kill. */
  const raw=(S.vampire && (k==="str"||k==="stam")) ? Math.max(S[k]||0, ATTR_FULL) : (S[k]||0);
  const v=clamp(raw,0,ATTR_CAP);
  return v<=ATTR_FULL ? v/ATTR_FULL : 1+(v-ATTR_FULL)/ATTR_FULL*2;
}
// ...this one for effects that would be silly if the overfill doubled them (need drain, rest)
function attrF1(k){ return Math.min(1, attrF(k)); }
// ...and this one for cooldowns, where the overfill should still be felt, but halved: a surge
// makes him quicker off the mark, it does not delete the cooldown
function attrF15(k){ return Math.min(1.5, attrF(k)); }
function attrOver(k){ return Math.max(0,(S[k]||0)-ATTR_FULL); }
function anyOverfill(){ return ATTRS.some(([,k])=>attrOver(k)>0); }
// earned training: capped at full, curved, and scaled by how fit he was to train at all
function trainAward(k, raw){
  const cur=S[k]||0;
  if(cur>=ATTR_FULL) return 0;
  const g=trainGain(cur, raw*trainEfficiency());
  if(g<=0) return 0;
  S[k]=Math.min(ATTR_FULL, cur+g);
  S.trainAcc=S.trainAcc||{};
  S.trainAcc[k]=(S.trainAcc[k]||0)+g;
  return g;
}
// the overfill bleeds off in real time, everywhere — home, park, mid-run
function attrTick(dt){
  if(!anyOverfill()) return;
  const d=dt/ATTR_DRAIN_SEC;
  for(const [,k] of ATTRS){
    if(S[k]>ATTR_FULL){
      S[k]=Math.max(ATTR_FULL, S[k]-d);
      if(S[k]<=ATTR_FULL){
        S[k]=ATTR_FULL;
        dogLog(attrName(k)+" HAS SETTLED BACK TO FULL.");
        beep(300,.12,"square",.035);
      }
    }
  }
}
function attrName(k){ const a=ATTRS.find(([,kk])=>kk===k); return a?a[0]:k; }
// Runs a batch of earned gains and says what it did. Returns true if anything actually landed —
// a maxed-out attribute silently earns nothing, and the caller can fall back to its own message.
function trainBatch(raw){
  const got=[];
  for(const [lb,k] of ATTRS){
    const g=trainAward(k, raw[k]||0);
    if(g>=0.05) got.push(lb.slice(0,3)+" +"+g.toFixed(1));
  }
  return got;
}
function trainSession(raw, prefix){
  const got=trainBatch(raw);
  if(!got.length) return false;
  toast((prefix?prefix+" ":"")+got.join("  "));
  beep(900,.05,"square",.04); setTimeout(()=>beep(1200,.06,"square",.04),70);
  renderDogLogStats();
  return true;
}
/* ==================== THE TRICK TREE ====================
   The three attributes are a dial you turn; these are things he can suddenly DO, bought with the
   same points. Deliberately small to start with and deliberately load-bearing: FETCH is what puts
   a ball in the room at all, so the very first point you ever spend changes what the game is.
   `req` names a trick that has to come first, so the tree has a shape rather than being a list. */
/* TWO TRUNKS OUT OF ONE ROOT. Everything on the LEFT is his own body - what he can be taught to
   do with it. Everything on the RIGHT is the care of him - the room, the routine, the things you
   do FOR him rather than the things he does. That split is the game's own split, so the tree
   should show it rather than hide it in a list.
   `x` is -1..1 across the panel and `y` is rows down from the root, both in tree units; `soon`
   marks a node that is drawn and reachable but has nothing behind it yet, so it says so instead
   of taking a point for nothing. */
const TREE_DOG="#e8c14a", TREE_CARE="#3fdc7a";
const TRICKS=[
  {k:"bond", name:"THE BOND", cost:0, req:null, root:true, x:0, y:0, side:"root",
   note:"WHERE EVERYTHING STARTS. HE IS YOURS."},

  // ---- his body ----
  {k:"fetch", name:"FETCH",     cost:1, req:"bond", x:-0.46, y:1, side:"dog",
   note:"A BALL IN THE ROOM \u2014 DRAG IT DOWN AND LET GO"},
  {k:"sit",   name:"SIT",       cost:1, req:"bond", x:-0.92, y:2, side:"dog",
   note:"SWIPE DOWN ON HIM AND HE SITS"},
  {k:"jump",  name:"JUMP CATCH",cost:1, req:"fetch", x:-0.40, y:2.6, side:"dog",
   note:"HE LEAVES THE FLOOR FOR A BALL OVER HIS HEAD"},
  {k:"roll",  name:"ROLL OVER", cost:1, req:"sit", x:-0.95, y:3.2, side:"dog",
   note:"SWIPE SIDEWAYS ON HIM AND HE ROLLS"},
  {k:"speak", name:"SPEAK",     cost:1, req:"roll", x:-0.72, y:4.2, side:"dog", soon:true,
   note:"ON THE WAY"},
  {k:"sprint",name:"SPRINT",    cost:1, req:"jump", x:-0.34, y:3.8, side:"dog", soon:true,
   note:"ON THE WAY"},
  {k:"guard", name:"GUARD",     cost:2, req:"sprint", x:-0.55, y:4.9, side:"dog", soon:true,
   note:"ON THE WAY"},

  // ---- the care of him ----
  {k:"bowls", name:"BIG BOWLS", cost:1, req:"bond", x:0.46, y:1, side:"care", soon:true,
   note:"ON THE WAY"},
  {k:"groom", name:"GROOMING",  cost:1, req:"bond", x:0.92, y:2, side:"care", soon:true,
   note:"ON THE WAY"},
  {k:"comfy", name:"COMFORT",   cost:1, req:"bowls", x:0.40, y:2.6, side:"care", soon:true,
   note:"ON THE WAY"},
  {k:"treats",name:"TREAT JAR", cost:1, req:"groom", x:0.95, y:3.2, side:"care", soon:true,
   note:"ON THE WAY"},
  {k:"vet",   name:"VET VISITS",cost:1, req:"comfy", x:0.34, y:3.8, side:"care", soon:true,
   note:"ON THE WAY"},
  {k:"home",  name:"A REAL HOME",cost:2, req:"vet", x:0.55, y:4.9, side:"care", soon:true,
   note:"ON THE WAY"},
];
function trickBy(k){ return TRICKS.find(t=>t.k===k); }
function trickColor(t){ return t.side==="care" ? TREE_CARE : t.side==="dog" ? TREE_DOG : "#fff"; }
// the root is free and always held: it is the trunk both sides grow out of, not a purchase
function hasTrick(k){ return k==="bond" || !!(S.tricks && S.tricks[k]); }
function trickReady(t){ return !hasTrick(t.k) && (!t.req || hasTrick(t.req)); }
function learnTrick(k){
  const t=trickBy(k);
  if(!t || hasTrick(k)) return;
  if(t.soon){ toast(t.name+" IS STILL IN TRAINING.",1); beep(220,.08); return; }
  if((S.pts||0)<t.cost){ toast("NOT ENOUGH SKILL POINTS.",1); beep(150,.1); return; }
  if(t.req && !hasTrick(t.req)){ toast("HE NEEDS "+trickBy(t.req).name+" FIRST.",1); beep(150,.1); return; }
  S.pts-=t.cost;
  S.tricks=S.tricks||{}; S.tricks[k]=1;
  /* FETCH is the one that changes the room. The ball has to actually arrive, and it arrives the
     way anything good arrives here: dropped on the carpet with a bounce in it. */
  if(k==="fetch"){
    S.ballOwned=true; S.todoBall=true; tickTodo("ball");
    BALL.off=false; BALL.carried=false; BALL.pcarried=false; BALL.held=false;
    BALL.x=0.30; BALL.z=0.86; BALL.hz=0.45; BALL.vx=0; BALL.vz=0; BALL.vh=0; BALL.cool=0.3;
    ballSyncY();
  }
  dogLog("BONES LEARNED "+t.name+"!");
  toast("BONES LEARNED "+t.name+"!");
  sfxTrickLearned();
  haptic(35);
  renderSkillPanel(); renderDogLog(true); renderMeters(); renderTodo();
}
function sfxTrickLearned(){
  [660,880,1100,1320].forEach((f,i)=>setTimeout(()=>beep(f,.09,"square",.05,{prio:2}),i*85));
}
/* ==================== DRAWING THE TREE ====================
   Laid out in tree units and fitted to whatever canvas it gets: `x` is -1..1 across and `y` is
   rows down. Edges first so the nodes sit on top of them, and a LIT edge (both ends owned) is
   drawn in its branch's colour at full weight - that lit path down from the root is the whole
   readout of how far you have come. */
let TREEHIT=[], TREESEL=null;
function treeLayout(w,h){
  const rows=Math.max(...TRICKS.map(t=>t.y));
  // the labels ride at the TOP beside the root now, so the bottom row gets the full padding
  const padX=28, padTop=26, padBot=14;
  const sx=(w-padX*2)/2, sy=(h-padTop-padBot)/Math.max(1,rows);
  const r=clamp(Math.min(sx*0.30, sy*0.44), 11, 22);
  return {r, X:(t)=>w/2+t.x*sx, Y:(t)=>padTop+t.y*sy};
}
function drawTree(t){
  const cv=$("#treecv"); if(!cv||!cv.clientWidth||!cv.clientHeight) return;
  const [ctx,w,h]=fit(cv);
  ctx.clearRect(0,0,w,h);
  const L=treeLayout(w,h);
  TREEHIT=[];
  for(const n of TRICKS){                                   // edges, under everything
    if(!n.req) continue;
    const p=trickBy(n.req); if(!p) continue;
    const lit=hasTrick(n.k), open=!lit && hasTrick(n.req);
    ctx.strokeStyle = lit ? trickColor(n) : open ? "#5a5a62" : "#2e2e36";
    ctx.lineWidth = lit ? 5 : open ? 3 : 2;
    ctx.beginPath(); ctx.moveTo(L.X(p),L.Y(p)); ctx.lineTo(L.X(n),L.Y(n)); ctx.stroke();
  }
  for(const n of TRICKS){
    const x=L.X(n), y=L.Y(n), got=hasTrick(n.k);
    const open =!got && (!n.req||hasTrick(n.req));
    const ready=open && !n.soon && (S.pts||0)>=n.cost;
    const col=trickColor(n);
    const rr=L.r*(n.root?1.15:1)*(TREESEL===n.k?1.12:1);
    ctx.beginPath(); ctx.arc(x,y,rr,0,7);
    ctx.fillStyle = got ? col : open ? "#23232b" : "#17171c";
    ctx.fill();
    ctx.lineWidth = TREESEL===n.k ? 4 : ready ? 3.5 : 2;
    ctx.strokeStyle = TREESEL===n.k ? "#fff" : (got||open) ? col : "#3a3a44";
    if(ready && TREESEL!==n.k) ctx.globalAlpha=0.55+0.45*Math.abs(Math.sin(t*2.4));
    ctx.stroke(); ctx.globalAlpha=1;
    // a tick for owned, its cost for a live one, two dots for one still in training
    ctx.fillStyle = got ? "#000" : open ? col : "#4a4a55";
    ctx.font="8px 'Press Start 2P',monospace"; ctx.textAlign="center"; ctx.textBaseline="middle";
    ctx.fillText(n.root ? "\u2726" : got ? "\u2713" : n.soon ? "\u00B7\u00B7" : String(n.cost), x, y+1);
    ctx.textBaseline="alphabetic"; ctx.textAlign="left";
    TREEHIT.push({k:n.k,x,y,r:rr+9});
  }
  ctx.save(); ctx.font="7px 'Press Start 2P',monospace"; ctx.textAlign="center";
  ctx.globalAlpha=0.8;
  ctx.fillStyle=TREE_DOG;  ctx.fillText("BONES", w*0.15, 12);
  ctx.fillStyle=TREE_CARE; ctx.fillText("CARE",  w*0.85, 12);
  ctx.restore(); ctx.textAlign="left";
}
function treeSelect(k){
  const t=trickBy(k); if(!t) return;
  TREESEL=k;
  const got=hasTrick(k), lock=t.req && !hasTrick(t.req);
  $("#treeName").textContent=t.name;
  $("#treeName").style.color=trickColor(t);
  $("#treeNote").textContent = got ? (t.root?t.note:"LEARNED. "+t.note)
    : lock ? "NEEDS "+trickBy(t.req).name+" FIRST"
    : t.soon ? "IN TRAINING \u2014 COMING SOON"
    : (S.pts||0)<t.cost ? t.note+"  \u2014  NEEDS "+t.cost+" POINT"+(t.cost===1?"":"S")
    : t.note+"  \u2014  TAP AGAIN TO LEARN ("+t.cost+"P)";
  $("#treeInfo").classList.toggle("buy", !got && !lock && !t.soon && (S.pts||0)>=t.cost);
}
$("#treecv").addEventListener("pointerdown",e=>{
  const cv=e.currentTarget, r=cv.getBoundingClientRect();
  const px=(e.clientX-r.left)/r.width*cv.clientWidth, py=(e.clientY-r.top)/r.height*cv.clientHeight;
  let best=null, bd=1e9;
  for(const n of TREEHIT){ const d=Math.hypot(px-n.x,py-n.y); if(d<n.r && d<bd){ bd=d; best=n; } }
  if(!best) return;
  /* One tap selects and explains, a second on the SAME node commits. A 30px circle is far too
     small a target to spend a point on by accident, and the note underneath is the only place
     there is room to say what the point actually buys. */
  const again=(TREESEL===best.k);
  treeSelect(best.k);
  if(again) learnTrick(best.k); else beep(520,.04,"square",.025);
});

/* ---- the skill point ---- */
// One per level, awarded at the moment the level is actually CONFERRED — the tap-through on the
// XP bar — not when addXP banks it, so the point and the ceremony land together and a level
// sitting unclaimed in the bar hasn't secretly paid out yet.
function awardSkillPoint(n){
  n=n||1;
  S.pts=(S.pts||0)+n;
  dogLog("SKILL POINT EARNED — OPEN THE LOG TO SPEND IT");
  renderDogLog(true);
  // the modal only interrupts when there is nothing else on screen to interrupt; anywhere else
  // the point simply banks and the log's gold badge is what tells you about it
  /* ASKED AGAIN WHEN IT FIRES. Checking canPromptSkill() only here answers "is this a good
     moment" about a moment 900ms in the past - and 900ms is long enough to tap GO OUT and be
     halfway into a DOGPARK run by the time the tree arrives on top of the controls. */
  if(canPromptSkill()) setTimeout(()=>{ if(canPromptSkill()) openSkillPanel(); }, 900);
}
function canPromptSkill(){
  if(PK.active || R.active || OUTING.active || EVO.active || XPLOCK) return false;
  if(MODE!=="home") return false;
  if($("#game").classList.contains("hidden")) return false;
  /* THE EVOLUTION PANEL IS NOT AN .overpanel and was invisible to this test, so a stage that
     conferred a point (5 and 99, which have no DOGCAM flicker to hide behind) got the skill tree
     dropped straight over the top of it 900ms later. */
  if(evoPanelOpen()) return false;
  for(const el of document.querySelectorAll(".overpanel.show, #choice.show")) return false;
  return true;
}
function evoPanelOpen(){ const e=$("#evoPanel"); return !!e && e.classList.contains("show"); }
function spendSkillPoint(k){
  if((S.pts||0)<=0) return;
  const cur=S[k]||0;
  if(cur>=ATTR_CAP){ toast(attrName(k)+" CANNOT HOLD ANY MORE.",1); beep(150,.1); return; }
  S.pts--;
  const over = cur>=ATTR_FULL;
  S[k]=Math.min(ATTR_CAP, cur+1);
  if(over){
    dogLog(attrName(k)+" PUSHED PAST FULL — "+Math.round(S[k])+" (IT WILL SETTLE)");
    beep(880,.08,"square",.05); setTimeout(()=>beep(1320,.10,"square",.05),90);
    setTimeout(()=>beep(1760,.14,"sine",.05),190);
  } else {
    dogLog(attrName(k)+" UP TO "+Math.round(S[k]));
    beep(700,.07); setTimeout(()=>beep(950,.09),80);
  }
  haptic(30);
  renderSkillPanel(); renderDogLogStats(); renderMeters();
  /* AND IT DOES NOT CLOSE ITSELF. Spending your last point used to shut the panel 420ms later,
     which is the game deciding you were finished looking. Points bank and keep; the panel is left
     open until the player closes it. */
}

const XPF=[]; let LVLFX=0; let MEMIMG=null;
const XPANIM={lvl:1,frac:0,snd:0,pauseT:0,parts:[],ready:false,danceOwed:false};
let XPLOCK=false;
/* Tapping the bar always ends at the tree. When there is a level waiting it is conferred first
   and the tree follows the celebration; when there is not, the tree comes straight up. The point
   itself is never spent by opening: it banks, and it stays banked until something is chosen. */
function xpBarTap(){
  if(XPANIM.ready){ xpLevelTap(); return; }        // the offer follows on its own clock
  if(PK.active||R.active||OUTING.active||EVO.active||XPLOCK||PARTY.on||evoPanelOpen()) return;
  openSkillPanel();
}
function xpLevelTap(){
  if(!XPANIM.ready) return;
  XPANIM.ready=false; XPANIM.pauseT=0.7;
  /* THE DANCE GOES HERE, not in addXP. The level is BANKED when the XP lands and CONFERRED when
     you tap the bar, and those can be minutes apart - dancing at the banking meant he celebrated
     a level nobody had claimed yet, usually while the player was looking at something else. He
     dances off to one side because the skill panel comes up over the bottom of the screen a
     moment later, and a dog dancing behind a menu is a dog nobody sees. */
  /* ...UNLESS HE IS ABOUT TO GROW. Levels 5, 10, 25 and 99 each fire a ceremony 0.7s from now,
     and a five-second dance started here was still running underneath it: he was hopping on the
     spot at PARTY_SIDE while the shrink/grow flicker played on a dog nobody could see, and the
     panel arrived over both. Growing up is the bigger event, so it goes first and gets the room
     to itself; the dance is owed and paid out the moment the ceremony is done with him. */
  const stageDue = S.pendingStage.length>0 && S.pendingStage[0]<=XPANIM.lvl+1;
  XPANIM.danceOwed = stageDue;
  if(!stageDue) partyStart(S.lvl, PARTY_LONG, true);
  const cvd=$("#dogcv"), w=cvd.clientWidth, h=cvd.clientHeight;
  beep(880,.09); setTimeout(()=>beep(1170,.12),110);
  for(let i=0;i<20;i++){
    const fromDog=i>=12, sp=40+Math.random()*90, a=Math.random()*Math.PI;
    XPANIM.parts.push({
      x: fromDog ? (CAM.x+0.12)*w : w-14,
      y: fromDog ? h*0.55 : h-20,
      vx: Math.cos(a)*sp*(Math.random()<0.5?-1:1),
      vy: -Math.abs(Math.sin(a))*sp-30,
      life: 0.9+Math.random()*0.4,
      red: Math.random()<0.2
    });
  }
}
const EVO={active:false,t:0,from:1,to:1,label:"",lines:"",after:null,swaps:[],end:3.9};
/* ==================== THE EVOLUTION ====================
   It used to be 3.9 seconds of the room flickering while the dog changed size somewhere behind
   the furniture, and the honest complaint about it was that you could not tell it had happened.
   This is the Pokemon shape instead, because that shape has been solving exactly this problem
   since 1996: STOP THE WORLD, take the character out of its scene, put it side-on against
   nothing at all, and let the silhouette flick between the two forms faster and faster until it
   cannot hold — then blow the screen out and show what he became.
   Six beats, each with its own length so the pacing can be tuned without touching the drawing:
     hush   the room drains away and he turns side-on
     rays   the light starts turning behind him
     morph  THE ALTERNATION. Small, large, small, large — accelerating, one ping per swap
     burst  it gives; the screen goes white and the rays fly off it
     reveal the white recedes and the new dog is standing there
     cheer  the banner, the confetti, and him bouncing on the spot
   REDUCED MOTION GETS ITS OWN COLUMN, not a scaled-down one. The alternation is a strobe, and a
   strobe is the single thing that setting exists to turn off — so it becomes one slow dissolve
   between the two forms with no flashing at all, and the whole thing runs shorter. */
const EVO_PH=[["hush",1.3,0.9],["rays",1.3,0.8],["morph",4.8,2.2],
              ["burst",0.6,0.5],["reveal",1.7,1.4],["cheer",2.0,1.7]];
function evoLen(i){ return EVO_PH[i][SETTINGS.reduceMotion?2:1]; }
function evoTotal(){ let s=0; for(let i=0;i<EVO_PH.length;i++) s+=evoLen(i); return s; }
function evoAt(tt){
  let s=0;
  for(let i=0;i<EVO_PH.length;i++){
    const L=evoLen(i);
    if(tt<s+L) return {ph:EVO_PH[i][0], k:clamp((tt-s)/L,0,1)};
    s+=L;
  }
  return {ph:"cheer", k:1};
}
/* WHEN IT SWAPS. Generated once at the start rather than derived per frame, because the DRAW and
   the AUDIO both have to agree on it exactly — a ping landing between two flips is the one thing
   that would make the acceleration read as noise. Geometric, floored at 75ms. */
function evoSwaps(){
  const out=[];
  if(SETTINGS.reduceMotion) return out;         // a dissolve has no swaps to ping
  const start=evoLen(0)+evoLen(1), len=evoLen(2);
  let tt=start, gap=0.42;
  while(tt<start+len-0.04){ out.push(tt); tt+=gap; gap=Math.max(0.075,gap*0.86); }
  return out;
}
function startEvo(label,from,to,lines,after){
  EVO.active=true; EVO.t=0; EVO.from=from; EVO.to=to; EVO.label=label; EVO.lines=lines;
  EVO.after=after||null;
  EVO.swaps=evoSwaps();
  EVO.end=evoTotal();
  hidePortrait(); closeStatus();
  const L0=evoLen(0), L1=evoLen(1), mS=L0+L1, bS=mS+evoLen(2), rS=bS+evoLen(3);
  beep(220,.5,"sine",.05);                                     // the room falling away
  setTimeout(()=>beep(150,.6,"triangle",.05), L0*450);
  for(let i=0;i<4;i++) setTimeout(()=>beep(330+i*110,.09,"square",.045), (L0+i*L1/4)*1000);
  EVO.swaps.forEach((st,i)=>setTimeout(()=>beep(520+Math.min(i,34)*46,.045,"square",.038,{prio:0}), st*1000));
  setTimeout(()=>{ beep(1900,.07,"square",.06); beep(120,.4,"sawtooth",.05); haptic([60,40,120]); }, bS*1000);
  setTimeout(()=>{ beep(659,.12,"sine",.06);
                   setTimeout(()=>beep(880,.12,"sine",.055),130);
                   setTimeout(()=>beep(1175,.14,"sine",.05),260);
                   setTimeout(()=>beep(1568,.34,"sine",.05),390); }, rS*1000);
  haptic([30,60,30,60,140]);
}
function NAME(){ return (S.dogName||"BONES")+(S.gen>1?[" II"," III"," IV"," V"," VI"][Math.min(S.gen-2,4)]:""); }
function DN(s){ return (S.dogName && S.dogName!=="BONES") ? String(s).replace(/BONES/g,S.dogName) : s; }
function stageName(l){ const v=l===undefined?S.lvl:l; return v<10?"PUPPY":v<25?"JUNIOR":(S.senior?"SENIOR":"PRIME"); }
function stageScale(l){ const v=l===undefined?S.lvl:l; return v<10?0.5:v<25?0.82:(S.senior?0.9:1); }
/* ---------- dog bed: sized to match BONES' current growth stage ---------- */
function dogStageIdx(){ return S.lvl<10?1:(S.lvl<25?2:3); }
function bedAdequate(){ return S.bedTier>=dogStageIdx(); }
function bedTierName(n){ return ["NONE","PUPPY BED","MEDIUM BED","LARGE BED"][n]||"NONE"; }
/* THE BED IS MEASURED IN FLOOR, NOT IN CANVAS. It used to be a flat fraction of the screen width
   plus a hardcoded x lifted from the pre-room layout - so it was the same size wherever it stood,
   and its `bx` pointed at a patch of carpet the bed had not occupied for three versions (which is
   what the poo drop and the SUPPLIES highlight were both aiming at). A width in floor units comes
   out right at any depth by construction, exactly like the dog. */
const BED_FLOOR_W=0.20, BED_FLOOR_STEP=0.085;   // half-width in floor units, per tier
const BED_ASPECT=0.62;                          // how deep it reads, against its own width
/* ONE SIZE, IN FLOOR UNITS, read by the art and by the tap target alike. A tier the dog has
   outgrown is genuinely smaller than he is, which is the whole point of the upgrade: a puppy bed
   under a prime dog should look like a bath mat under a wolf. */
function bedFloorR(){
  const sizeTier = S.bedTier>0 ? S.bedTier : dogStageIdx();  // unowned: outline the size he needs
  return BED_FLOOR_W+BED_FLOOR_STEP*(sizeTier-1);
}
function bedRect(w,h){
  const z=SPOT.bed.z, r=bedFloorR();
  const bw2=r*2*rmHW(z)*w;
  const bh2=bw2*BED_ASPECT*0.5;
  const bx=rmX(SPOT.bed.x,z)*w-bw2/2;
  return {bx,bw2,bh2};
}
/* The wicker-basket bed that used to stand against the back wall is gone: his bed is the rug in
   the middle of the room now, drawn by drawBed() with the floor. Removed rather than left
   unreferenced - an orphan draw routine is the same hazard as the orphan BED position that caused
   the v0.344a sleep loop, and this file has now been bitten by that twice. */
const LVLREWARDS={3:"SPIKED COLLAR IN SHOP",8:"RED BANDANA IN SHOP",14:"BRASS BELL IN SHOP",18:"AGILITY TRAINING UNLOCKED",25:"BONE CHARM IN SHOP",35:"STEEL TAG IN SHOP",45:"LUCKY ROPE IN SHOP",55:"LITTER OPTION UNLOCKED",70:"SHADOW LEASH IN SHOP",85:"CHAIN COLLAR IN SHOP"};
/* Tripled overall - a level is meant to be a week, not an evening - but HALVED for the first five.
   The opening levels are where the game is teaching you what the buttons do, and making someone
   grind through that is charging them for the tutorial. */
/* The opening five are where the game is teaching you what the buttons do. They were already
   half price; a further quarter off makes the first hour move at the pace the tutorial needs. */
function xpNeed(l){ return (l<=5 ? 1.125 : 3)*(20+l*8); }
const LVL_CAP=99;                         // hard — no XP and no levels past this
function addXP(n){
  if(n<=0||S.lvl>=LVL_CAP) return;
  S.xp+=n;
  XPF.push({x:0.40+Math.random()*0.18, y:0.58, life:1.3, txt:"+"+n+" XP"});
  let gained=0;
  while(S.xp>=xpNeed(S.lvl) && S.lvl<LVL_CAP){
    S.xp-=xpNeed(S.lvl); S.lvl++; gained++;
    LVLFX=1.2;
    if(S.lvl===15) tickTodo("lvl5");
    sfxLevelUp(); haptic(40);
    toast("LEVEL "+S.lvl+"!"+(LVLREWARDS[S.lvl]?" "+LVLREWARDS[S.lvl]:""));
    if(S.lvl===5) S.pendingStage.push(5);
    if(S.lvl===10) S.pendingStage.push(10);
    if(S.lvl===25) S.pendingStage.push(25);
    if(S.lvl===99 && !S.lifePathChosen) S.pendingStage.push(99);
    renderShop(); renderMeters();
  }
  // ...and no dance here: the level is only BANKED at this point. xpLevelTap does the show.
  // at the cap the bar sits full and nothing banks behind it — the last award can arrive with
  // far more XP than the final level needed, and none of it is worth anything
  if(S.lvl>=LVL_CAP) S.xp=Math.min(S.xp, xpNeed(LVL_CAP));
}
// cTxt/cFn are optional — a third, visually quieter escape hatch for dialogs that force a real
// pick between two live options (nothing to compare against yet, changed your mind, opened it
// by accident) so the player is never stuck having to commit to one of two choices they didn't
// actually want. Screens with a real "not now"/"cancel" already built into bTxt don't need it.
function openChoice(title,lines,aTxt,aFn,bTxt,bFn,cTxt,cFn){
  $("#chTitle").textContent=DN(title); $("#chLines").innerHTML=DN(lines);
  const A=$("#chA"),B=$("#chB"),C=$("#chC");
  A.textContent=aTxt; A.onclick=()=>{ $("#choice").classList.remove("show"); aFn&&aFn(); };
  if(bTxt){ B.style.display=""; B.textContent=bTxt; B.onclick=()=>{ $("#choice").classList.remove("show"); bFn&&bFn(); }; }
  else B.style.display="none";
  if(cTxt){ C.style.display=""; C.textContent=cTxt; C.onclick=()=>{ $("#choice").classList.remove("show"); cFn&&cFn(); }; }
  else C.style.display="none";
  $("#choice").classList.add("show");
}

/* ===================== THE GROWTH SPURT =====================
   Evolving used to be a white flash on the DOGCAM and a dialog. It is the single biggest thing
   that happens to this dog across a whole playthrough, so it now takes the entire screen, above
   everything else, and is celebrated properly. The burial hands it the screen mid-pour and waits
   for it — see pkBuryEvoCheck. */
const EVO_STAGES={
  /* NO PORTRAIT ON THIS ONE. The savage face belongs to a dog mid-run with everything on the
     line; opening the gates is an invitation, and being snarled at while you read it made the
     park look like a punishment. pic:null leaves the frame out entirely rather than swapping in
     a happier picture, because the rays and the title carry this screen on their own. */
  5:  {kicker:"A NEW WORLD OPENS",  title:"THE DOGPARK IS OPEN!", lines:"SURVIVE THE WAVES.<br>BANK BIG XP AT THE RED GATE.<br><br>IF HE GETS CAUGHT, YOU LOSE IT ALL ☠", pic:null},
  10: {kicker:"HE'S GROWING UP",    title:"BONES IS A JUNIOR!",   lines:"BIGGER. STRONGER. FASTER.<br><br>COMING UP:<br>BRASS BELL — LV.14<br>AGILITY TRAINING — LV.18<br>BONE CHARM — LV.25", pic:"happy"},
  25: {kicker:"PEAK CONDITION",     title:"BONES IS IN HIS PRIME!",lines:"FULL SIZE. TOP FORM MULTIPLIERS<br>ON EVERY SINGLE RUN.<br><br>AHEAD:<br>STEEL TAG — LV.35<br>LUCKY ROPE — LV.45<br>THE LITTER — LV.55<br>THE CROSSROADS — LV.99", pic:"happy"},
  99: {kicker:"THE CROSSROADS",     title:"A LIFE'S CHOICE",      lines:"NINETY-NINE LEVELS TOGETHER.<br>HE HAS GIVEN YOU EVERYTHING.<br><br>WHAT COMES NEXT IS UP TO YOU.", pic:"happy"}
};
let EVO_DONE=null;
function openEvoPanel(stg, onDone){
  const d=EVO_STAGES[stg] || EVO_STAGES[10];
  EVO_DONE=onDone||null;
  $("#evoKicker").textContent=d.kicker;
  $("#evoTitle").innerHTML=DN(d.title);
  $("#evoLvl").textContent="LV. "+S.lvl+"  —  "+stageName();
  $("#evoLines").innerHTML=DN(d.lines);
  const img=$("#evoImg");
  $("#evoImgWrap").style.display = d.pic ? "" : "none";
  if(d.pic){
    img.src=PORTRAITS[d.pic]||PORTRAITS.happy;
    img.style.animation="none"; void img.offsetWidth; img.style.animation="";   // replay the pop
  }
  $("#evoGo").textContent = stg===5 ? "GO THERE NOW" : stg===99 ? "CHOOSE" : "CONTINUE";
  // ...and the only stage you can decline is the one that would take you somewhere
  $("#evoNo").style.display = stg===5 ? "" : "none";
  $("#evoPanel").classList.add("show");
  $("#evoPanel").dataset.stg=String(stg);
  evoSparkBurst();
  haptic([40,60,40,60,120]);
  for(let i=0;i<7;i++) setTimeout(()=>beep(300+i*140,.09,"square",.05), i*110);
  setTimeout(()=>{ beep(880,.14,"sine",.06); setTimeout(()=>beep(1175,.14,"sine",.055),120);
                   setTimeout(()=>beep(1568,.3,"sine",.05),250); }, 850);
}
// real DOM confetti rather than another canvas pass — it has to sit above every canvas there is
function evoSparkBurst(){
  const p=$("#evoPanel");
  for(const old of p.querySelectorAll(".evoSpark")) old.remove();
  if(SETTINGS.reduceMotion) return;
  for(let i=0;i<26;i++){
    const el=document.createElement("div");
    el.className="evoSpark";
    const a=Math.random()*6.283, r=90+Math.random()*150;
    el.style.left="50%"; el.style.top="42%";
    el.style.background=Math.random()<0.35?"#fff":"#e8c14a";
    el.animate([
      {transform:"translate(-50%,-50%) scale(1)", opacity:1},
      {transform:"translate("+(Math.cos(a)*r-50)+"%,"+(Math.sin(a)*r-50)+"%) scale(0)", opacity:0}
    ],{duration:900+Math.random()*700, easing:"cubic-bezier(.1,.8,.3,1)", fill:"forwards"});
    p.appendChild(el);
  }
}
/* DECLINING THE PARK. The gates stay open - the stage is already conferred and the to-do already
   ticked - so this is only a choice about where you are standing right now, and GO TO DOGPARK on
   the home screen is waiting whenever you want it. */
$("#evoNo").onclick=()=>{
  $("#evoPanel").classList.remove("show");
  for(const old of $("#evoPanel").querySelectorAll(".evoSpark")) old.remove();
  beep(420,.06); LVLFX=1.0;
  const done=EVO_DONE; EVO_DONE=null;
  if(done) done();
  toast("THE PARK IS OPEN WHENEVER YOU ARE — GO TO DOGPARK.",1);
};
$("#evoGo").onclick=()=>{
  const stg=Number($("#evoPanel").dataset.stg||10);
  $("#evoPanel").classList.remove("show");
  for(const old of $("#evoPanel").querySelectorAll(".evoSpark")) old.remove();
  beep(700,.07); LVLFX=1.0;
  const done=EVO_DONE; EVO_DONE=null;
  // the two stages that actually branch the game still do what they always did
  if(stg===5){ if(done) done(); startPark(); return; }
  if(stg===99){ if(done) done(); openLifeChoice(); return; }
  if(S.bedTier>0 && !bedAdequate()) setTimeout(()=>toast("HE'S OUTGROWN HIS BED — TIME FOR A BIGGER ONE",1),1500);
  if(done) done();
};
/* ONE THING AT A TIME. The DOGCAM's shrink/grow flicker is 3.9 seconds of the whole point of the
   stage - him actually getting bigger - and it used to play with the panel already over it, which
   is why the evolution "didn't play correctly": there was nothing wrong with it, you just could
   not see it. The order now is flicker, beat, panel, and only once the panel is dismissed does he
   get his celebration. */
function fireStageCeremony(stg){
  if(stg===5) tickTodo("park");
  const open=()=>openEvoPanel(stg, evoCelebrate);
  if(stg===10){ startEvo("A JUNIOR",0.5,0.82,"",open); return; }
  if(stg===25){ startEvo("IN HIS PRIME",0.82,1,"",open); return; }
  open();
}
/* The dance the level owed him, paid after the ceremony rather than under it. A short beat first
   so the panel is visibly gone and any screen change it started (the park, the crossroads) has
   happened - partyStart's own guards can then see where they are. */
function evoCelebrate(){
  if(!XPANIM.danceOwed) return;
  XPANIM.danceOwed=false;
  setTimeout(()=>{
    if(MODE!=="home" || XPLOCK || evoPanelOpen()) return;
    partyStart(S.lvl, PARTY_LONG, true);
    if(!PARTY.on) return;
    // ...and the tree follows into the dance exactly as it does for a plain level
    if((S.pts||0)>0 && canPromptSkill()) setTimeout(()=>{ if(canPromptSkill()) openSkillPanel(); }, 900);
  }, 420);
}
function openLifeChoice(){
  XPLOCK=true;
  openChoice("A CROSSROADS",
    "BONES HAS REACHED HIS PRIME.<br>WOULD YOU LIKE HIM TO BECOME A SENIOR?<br><br>SENIOR: NEEDS EASE, HE SLOWS DOWN,<br>AND ONE DAY HE'LL SAY GOODBYE,<br>LEAVING A LEGACY BEHIND.<br><br>PRIME FOREVER: PEAK CONDITION. NO END.",
    "BECOME SENIOR",()=>{ S.senior=true; S.lifePathChosen=true; XPLOCK=false;
      startEvo("A SENIOR",1,0.9,"HIS NEEDS EASE (-40% DECAY)<br>AND HE TAKES LIFE SLOWER NOW.<br><br>CHERISH THESE DAYS."); },
    "STAY PRIME FOREVER",()=>{ S.lifePathChosen=true; XPLOCK=false; toast("BONES STAYS IN HIS PRIME. FOREVER."); });
}
function startGoodbye(){
  sfxGoodbye(); haptic([80,100,80,100,150]);
  openChoice("GOODBYE, BONES",
    "AFTER A GOOD, LONG LIFE, BONES PASSED<br>PEACEFULLY IN HIS SLEEP.<br><br>HIS PHOTO NOW HANGS ON THE WALL.<br>HE LEAVES A LEGACY TAG"+(S.litter?"<br>\u2014 AND A PUP WHO'S BEEN WAITING.":"<br>FOR THE PUPPY WHO COMES NEXT."),
    "CONTINUE", successor);
}
function successor(){
  S.memorialSrc=PORTRAITS.happy; MEMIMG=new Image(); MEMIMG.src=S.memorialSrc;
  S.owned.legacy=1; S.equipped="legacy";
  S.gen++; S.lvl=1; S.xp=0; S.senior=false; S.seniorDays=0; S.lifePathChosen=false; S.litter=false;
  S.str=ATTR_START; S.stam=ATTR_START; S.vit=ATTR_START; S.pts=0; S.trainAcc={};
  S.sick=false; S.sickTimer=0; S.wellTimer=0;
  Object.assign(S,{hunger:70,thirst:70,energy:85,clean:85,fun:75,mood:75});
  BOWL.level=1; FBOWL.level=1;
  toast(NAME()+" HAS BEEN ADOPTED. THE LEGACY CONTINUES.");
  renderMeters(); renderShop();
}
function triggerDeath(){
  beep(60,.9,"sawtooth",.04);
  haptic([100,50,100,50,200]);
  if(PK.active){ PK.active=false; showScreen("home"); }
  if(R.active){ R.active=false; showScreen("home"); }
  OUTING.active=false;
  clearInterval(_vetInterval); _vetInterval=null;
  const hasSave=S.lastSaveAt!=null;
  const canVet=S.money>=500;
  if(canVet){
    let secs=30;
    const vetMsg=()=>"HE WENT TO SLEEP WITHOUT FOOD OR WATER<br>AND DIDN'T WAKE UP.<br><br>EMERGENCY VET — HURRY! "+secs+"s LEFT.";
    openChoice(
      "BONES DIDN'T MAKE IT",
      vetMsg(),
      "EMERGENCY VET — $500",
      ()=>{ clearInterval(_vetInterval); _vetInterval=null; doVet(); },
      hasSave?"LOAD LAST SAVE":"CONTINUE",
      ()=>{ clearInterval(_vetInterval); _vetInterval=null; doRewind(); }
    );
    _vetInterval=setInterval(()=>{
      secs--;
      if(secs<=0){
        clearInterval(_vetInterval); _vetInterval=null;
        $("#choice").classList.remove("show");
        doRewind();
        return;
      }
      $("#chLines").innerHTML=DN(vetMsg());
    },1000);
  } else {
    openChoice(
      "BONES DIDN'T MAKE IT",
      hasSave
        ? "HE WENT TO SLEEP WITHOUT FOOD OR WATER<br>AND DIDN'T WAKE UP.<br><br>LOAD YOUR LAST SAVE AND TAKE BETTER<br>CARE OF HIM."
        : "BONES NEEDED CARE AND DIDN'T GET IT.<br><br>FEED HIM. WATER HIM. HE NEEDS YOU.",
      hasSave?"LOAD LAST SAVE":"CONTINUE",
      doRewind
    );
  }
}
function doVet(){
  S.money-=500;
  S.dead=false; S.neglectNight=false; S.neglectNights=0;
  S.sick=false; S.sickTimer=0; S.wellTimer=0;
  S.hunger=clamp(S.hunger+45,0,100); S.thirst=clamp(S.thirst+45,0,100);
  S.energy=clamp(S.energy+30,0,100); S.mood=clamp(S.mood+25,0,100);
  if($("#game").classList.contains("hidden")){ $("#start").classList.add("hidden"); $("#game").classList.remove("hidden"); }
  showScreen("home");
  renderMeters(); renderShop(); renderTodo();
  beep(440,.08); setTimeout(()=>beep(554,.08),130); setTimeout(()=>beep(660,.1),260);
  toast("VET VISIT: $500. BONES IS RECOVERING.",1);
}
function doRewind(){
  clearInterval(_vetInterval); _vetInterval=null;
  const ok=loadGame();
  S.dead=false; S.neglectNight=false; S.neglectNights=0;
  if(!ok){
    S.sick=false; S.sickTimer=0; S.wellTimer=0;
    Object.assign(S,{hunger:35,thirst:35,energy:40,clean:40,fun:40,mood:40});
  }
  if($("#game").classList.contains("hidden")){ $("#start").classList.add("hidden"); $("#game").classList.remove("hidden"); }
  showScreen("home");
  renderMeters(); renderShop(); renderTodo();
  toast("TAKE BETTER CARE OF HIM.",1);
}
function dogMoodState(){
  if(R.active && R.mode==="daily") return "savage";
  const a=avgStat();
  if(a>=65) return "happy";
  if(a<=35) return "sad";
  return "neutral";
}

/* ---------- portraits (tap BONES on DOGCAM) ---------- */
function portraitState(){
  const a=avgStat();
  if(a<=35) return "sad";
  if(Object.values({h:S.hunger,t:S.thirst,e:S.energy,c:S.clean}).some(v=>v<25)) return "confused"; // something's wrong but he can't tell you what
  if(a>=65) return "happy";
  return "content";
}
let portraitT=0;
function showPortrait(state,dur){
  const p=$("#portrait");
  clearInterval(showPortrait._tv);
  if(state==="treat"){
    let f=0; $("#portraitImg").src=TREATIMG[0].src;
    showPortrait._tv=setInterval(()=>{ f^=1; $("#portraitImg").src=TREATIMG[f].src; },420);
  } else $("#portraitImg").src = PORTRAITS[state];
  const lb=$("#portraitLb");
  lb.textContent = {confused:"CONFUSED",happy:"HAPPY",sad:"SAD",content:"CONTENT",savage:"SAVAGE-THIRSTY",treat:"MORE?? PLEASE"}[state];
  lb.className = state==="savage" ? "red" : "";
  p.classList.toggle("savage", state==="savage");
  // place the card on whichever side of BONES has more room right now
  if(CAM.x < 0.5){ p.style.right="8px"; p.style.left="auto"; }
  else { p.style.left="8px"; p.style.right="auto"; }
  p.classList.add("show");
  clearTimeout(portraitT);
  portraitT=setTimeout(hidePortrait, dur||2600);
  beep(state==="savage"?120:560, .07, state==="savage"?"sawtooth":"square");
}
function hidePortrait(){ clearTimeout(portraitT); clearInterval(showPortrait._tv); $("#portrait").classList.remove("show"); }
const stAnim={t:0,i:0,src:""};
function statusFrame(dt){
  stAnim.t+=dt;
  if(stAnim.t>=0.4){ stAnim.t=0; stAnim.i++; }
  const arr = STATPORT[portraitState()] || STATPORT.content;
  const want = arr[stAnim.i % arr.length];
  if(want!==stAnim.src){ stAnim.src=want; $("#stImg").src=want; }
}
function tapBowl(kind){
  const now=performance.now()/1000;
  const T=TAPS[kind];
  T.combo = (now-T.t<0.6) ? Math.min(3,T.combo+1) : 1;
  T.t=now;
  if(kind==="water"){
    if(BOWL.level>0.97){ beep(300,.04); return toast("WATER BOWL IS FULL."); }
    BOWL.level=Math.min(1,BOWL.level+1/3);
    if(!S.firstWater){ S.firstWater=true; addXP(6); toast("GOOD! FRESH WATER. +6 XP"); }
    S.twW=true; if(S.twF) tickTodo("bowls");
    S.dWater=true; if(S.dFood) tickTodo("d_nour");
    addXP(T.combo); beep(560+T.combo*70,.05);
    if(S.thirst<80) drawAttention("drinkgo");
  } else {
    if(FBOWL.level>0.97){ beep(300,.04); return toast("FOOD BOWL IS FULL."); }
    if(S.kibble<=0){ toast("NO KIBBLE \u2014 RESTOCK IN THE SHOP",1); return openShopPanel(); }
    S.kibble--; FBOWL.level=Math.min(1,FBOWL.level+1/3);
    if(!S.firstFood){ S.firstFood=true; addXP(6); toast("GOOD! HE'S FED. +6 XP"); }
    S.twF=true; if(S.twW) tickTodo("bowls");
    S.dFood=true; if(S.dWater) tickTodo("d_nour");
    addXP(T.combo); beep(520+T.combo*70,.05);
    renderMeters();
    if(S.hunger<80) drawAttention("eatgo");
  }
}
function drawAttention(st){
  const busy=["rest","come","fetch","wash","drink","eat","beg","stay","begwait"].includes(CAM.state)||CAM.bedTarget||WASH.pending;
  if(busy||R.active||OUTING.active) return;
  CAM.state=st; CAM.until=99; CAM.t=0; CAM.fi=0;
}
function buyBed(){
  if(S.bedTier>0) return;
  if(S.money<25) return toast("NOT ENOUGH \u2014 THE BED IS $25",1);
  S.money-=25; S.bedTier=dogStageIdx();
  tickTodo("bed");
  toast("BONES HAS A PROPER BED NOW."); heartsBurst(2); beep(700,.08);
  renderMeters(); renderSupplies();
}
function buyBiggerBed(){
  if(bedAdequate()) return;
  if(S.money<45) return toast("NOT ENOUGH \u2014 A BIGGER BED IS $45",1);
  S.money-=45; S.bedTier=dogStageIdx();
  toast("A BIGGER BED \u2014 HE CAN STRETCH OUT NOW."); heartsBurst(2); beep(700,.08); setTimeout(()=>beep(950,.09),100);
  renderMeters(); renderSupplies(); renderShop();
}
// up to 5 balls total (one in play + spares in supplies) \u2014 the spares exist so a ball that's
// truly gone for good (lost off-screen, or just worn out) never leaves the player stuck without
// one. The first purchase places a ball immediately; every one after that banks as stock instead.
const BALL_MAX=5;
function ballTotalOwned(){ return (S.ballOwned?1:0)+S.ballStock; }
function buyBall(){
  if(S.lvl<2){ toast("A BALL UNLOCKS AT LV.2",1); return; }
  if(ballTotalOwned()>=BALL_MAX){ toast("5 BALLS IS PLENTY \u2014 THAT'S THE MOST HE CAN KEEP.",1); return; }
  if(S.money<5){ toast("NOT ENOUGH \u2014 A BALL IS $5",1); return; }
  S.money-=5;
  if(!S.ballOwned){
    S.ballOwned=true;
    BALL.x=0.28; BALL.y=0.795; BALL.vx=0; BALL.vy=0; BALL.off=false; BALL.carried=false; BALL.pcarried=false;
    tickTodo("ball");
    toast("A BALL! FLING IT \u2014 HE'LL BRING IT BACK.");
  } else {
    S.ballStock++;
    toast("A SPARE BALL \u2014 "+S.ballStock+" WAITING IN SUPPLIES.");
  }
  beep(700,.07); setTimeout(()=>beep(950,.09),100);
  renderMeters(); renderSupplies(); renderShop(); renderTodo();
}
// pulls one ball from supplies and sets it down fresh \u2014 the manual fix for a ball that's stuck,
// lost, or just to swap the one currently rolling around for a new one
function placeBallFromStock(){
  if(S.ballStock<=0) return;
  S.ballStock--;
  BALL.x=clamp(CAM.x+CAMDWF*0.6,0.03,0.95); BALL.y=0.795; BALL.vx=0; BALL.vy=0;
  BALL.off=false; BALL.carried=false; BALL.pcarried=false; BALL.cool=0.5;
  toast("A FRESH BALL, SET DOWN.");
  beep(700,.06); setTimeout(()=>beep(950,.07),90);
  renderSupplies();
}
