let _vetInterval = null;
// panels that are safe to dismiss with a stray DOGCAM tap -- "browse and back out" style menus
// opened from the home screen. Deliberately excludes: #choice (forced confirmations -- also
// physically covers #cam so it's unreachable anyway), #pre/#result/#bedtimePanel/#welcomeBack
// (run-flow and forced-narrative beats that shouldn't vanish on an incidental tap).
const CAM_DISMISS_PANELS = [
  ["goout","goClose"], ["shopPanel","shopClose"], ["supplies","supClose"],
  ["todoPanel","todoClose"], ["mailPanel","mailClose"], ["menuPanel","menuClose"],
  ["dlogPanel","dlogClose"], ["skillPanel","skillLater"],
  ["careGuidePanel","careClose"], ["settingsPanel","settingsClose"],
  ["nourish","nourishClose"], ["moneyPick","mpCancel"], ["mystPanel","mystClose"],
  ["pinPanel","pinClose"],
];
// returns true if a panel was open and got closed -- callers use this to swallow the tap
function dismissOpenCamPanel(){
  for(const [panelId,closeId] of CAM_DISMISS_PANELS){
    const p=$("#"+panelId);
    if(p && p.classList.contains("show")){ $("#"+closeId).click(); return true; }
  }
  return false;
}
$("#dogcv").addEventListener("pointerdown",e=>{
  if(BURY.on) return;                            // the burial owns every tap while it runs
  if(R.active||OUTING.active||PK.active) return; // BONES is out
  if(WASH.active) return;             // scrubbing uses drag, not taps
  if(dismissOpenCamPanel()) return;   // a stray tap on DOGCAM backs out of whatever panel is open first
  const r=e.currentTarget.getBoundingClientRect();
  const fx=(e.clientX-r.left)/r.width, fy=(e.clientY-r.top)/r.height;
  // ...unless the slats are down, in which case there is nothing to catch him through
  if(mystHitWindow(fx,fy) && !blindsSealing()){ mystOpen(); return; }   // caught him at the glass
  /* THE WINDOW IS ITS OWN BUTTON, and now it is a swipeable one. A press that lands on the glass
     is remembered here and resolved on pointerup: down = shut the blinds, up = open them, and a
     press that goes nowhere is a tap. The broken pane keeps its own tap, but only while the slats
     are up - with them down the shutters own the window and the glazier moves inside their panel,
     or a shut blind would be a way to lose the repair entirely. */
  if(winHit(fx,fy)){
    WINGES.on=true; WINGES.x=fx; WINGES.y=fy; WINGES.t=performance.now()/1000;
    try{ e.currentTarget.setPointerCapture(e.pointerId); }catch(_){}
    return;
  }
  if(S.memorialSrc && fx>0.12 && fx<0.28 && fy>0.12 && fy<0.34){ // the photo on the wall
    $("#portraitImg").src=S.memorialSrc;
    const lb=$("#portraitLb"); lb.textContent="IN LOVING MEMORY"; lb.className="";
    $("#portrait").classList.toggle("savage",false);
    $("#portrait").style.right="auto"; $("#portrait").style.left="8px";
    $("#portrait").classList.add("show");
    clearTimeout(portraitT); portraitT=setTimeout(hidePortrait,3200);
    beep(420,.1); return;
  }
  // righting the bot is allowed even from work — he IS the remote-care mechanism, so leaving
  // him face-down and untappable during a shift would strand BONES with nobody able to help
  if(S.owned.robot && ROBOT.state==="down" && Math.abs(fx-rmX(ROBOT.x,ROBOT_Z))<0.10 &&
     Math.abs(fy-rmY(ROBOT_Z))<0.22){ botRight(); return; }
  if(atWorkNow() && !S.owned.robot){ blockAtWork(); return; }
  // a tap that lands on BONES belongs to BONES — wall items never steal it
  const onDogNow = fx>CAM.x-0.02 && fx<CAM.x+CAMDWF+0.04 && fy>0.30;
  if(S.brushOwned && !BRUSH.held && !onDogNow && Math.hypot(fx-BRUSH_X,fy-BRUSH_Y)<0.055){
    BRUSH.held=true; BRUSH.x=fx; BRUSH.y=fy;
    try{ e.currentTarget.setPointerCapture(e.pointerId); }catch(_){}
    beep(430,.04); return;
  }
  const spx=SPONGE.held?SPONGE.x:SPONGE_X, spy=SPONGE.held?SPONGE.y:SPONGE_Y;
  if(!SPONGE.held && onDogNow){ /* fall through to the dog */ }
  else if(Math.hypot(fx-spx,fy-spy)<0.06){                  // grab the sponge off the wall
    if(S.shampooPct<=0){
      openChoice("NO DOG SHAMPOO", "BONES NEEDS SHAMPOO BEFORE YOU CAN WASH HIM.",
        "GO TO SHOP", ()=>openShopPanel(), "CANCEL", ()=>{});
      beep(300,.1); return;
    }
    SPONGE.held=true; SPONGE.x=fx; SPONGE.y=fy;
    try{ e.currentTarget.setPointerCapture(e.pointerId); }catch(_){}
    for(let i=0;i<5;i++) DRIPS.push({x:fx+(Math.random()-0.5)*0.03, y:fy+0.015, vy:0.14+Math.random()*0.2, life:0.6+Math.random()*0.3});
    beep(480,.04); return;
  }
  // poo piles: tap to pick up \u2014 checked before the ball/bowls/bed so an accident
  // sitting in front of them always wins the tap, since it can't be moved out of the way
  for(let i=0;i<POOS.length;i++){
    // ...tested where the pile is DRAWN, which is no longer where its floor x happens to be
    const pz=(POOS[i].z===undefined?0.80:POOS[i].z);
    if(Math.abs(fx-rmX(POOS[i].x,pz))<0.055 && Math.abs(fy-rmY(pz))<0.06){
      POOS.splice(i,1); addXP(2); beep(500,.05);
      toast("PICKED UP. GOOD OWNER."); return;
    }
  }
  // grab the ball - tested against where it actually IS on the glass, which is now derived from
  // its floor position rather than stored, so a ball far up the room has a small grab radius too
  if(S.ballOwned && !BALL.pcarried && (()=>{ const p=ballScreen();
        return Math.hypot(fx-p.x,(fy-p.y)*1.3) < 0.055*Math.max(0.7,p.sc); })()){
    BALL.held=true; BALL.settle=null;      // picking it up ends whatever drop was easing home
    BALL.grab={t:performance.now()/1000, x:fx, y:fy};
    BALL.tz=rmZof(fy); BALL.tx=rmXof(fx,BALL.tz);
    BALL.trail=[]; BALL.vx=0; BALL.vz=0; BALL.vh=0;
    // the band is pinned where you took hold of it, and everything after is measured from there
    SLING.on=true; SLING.ax=fx; SLING.ay=fy; SLING.x=fx; SLING.y=fy;
    SLING.draw=0; SLING.peak=0; SLING.tickT=0;
    SLING.deck=false; SLING.pull=0; SLING.peakPull=0; SLING.maxed=false;
    sfxSlingGrab();
    try{ e.currentTarget.setPointerCapture(e.pointerId); }catch(_){}
    return;
  }
  /* Bowls and bed, hit-tested off the SAME rects the draw uses. They used to be recomputed here
     from the same magic numbers, which held together only for as long as nothing moved - and then
     the furniture moved. */
  const FR=camFurnRects(r.width,r.height);
  const px=fx*r.width, py=fy*r.height;
  const inRect=(q,padX,padY)=>px>=q.x-padX && px<=q.x+q.w+padX &&
                              py>=q.y-q.h-padY && py<=q.y+padY;
  if(inRect(FR.water,6,10)){ tapBowl("water"); return; }
  if(inRect(FR.food, 6,10)){ tapBowl("food");  return; }
  /* HIM. His sprite is drawn CENTRED on his floor spot now, not hung off its left edge, so the
     old "from CAM.x rightwards" box tested a strip beside him rather than him. */
  const dogSx=rmX(CAM.x,CAM.z), dogSy=rmY(CAM.z);
  const onDog = Math.abs(fx-dogSx) < Math.max(0.06,CAMDWF*0.55) &&
                fy > dogSy - dogBodyF()*1.25 && fy < dogSy + 0.03;
  if(S.pup.owned && fx>PUP.x-0.02 && fx<PUP.x+PUP.w+0.04 && fy>0.55){
    S.sel="pup"; renderDogSel(); flashDogSel();
    S.pup.mood=clamp(S.pup.mood+2,0,100); tickTodo("p_pet");
    heartsBurst(1); beep(720,.05);
    return;
  }
  if(onDog && S.sel!=="bones"){ S.sel="bones"; renderDogSel(); flashDogSel(); }
  if(onDog && CAM.state==="begwait"){
    S.mood=clamp(S.mood+4,0,100); heartsBurst(2); beep(760,.07);
    tickTodo("j_trick");
    toast("SHAKE! GOOD BOY!");
    return;
  }
  if(onDog){
    PET.down=true; PET.px=fx; PET.py=fy; PET.stroked=false;
    PET.sx=fx; PET.sy=fy;          // where the gesture STARTED, for the swipe read on release
    clearTimeout(PET.lp);
    PET.lp=setTimeout(()=>{ if(!PET.stroked) openStatus(); },550); // long-press = status
    petStroke(0.4);
    return;
  }
  /* THE BAR IS THE DOOR TO THE TREE - full, it confers the level and then opens it; not full, it
     just opens it, because a player who wants to see what is ahead should not have to wait for a
     level to be sitting unclaimed. It is tested LAST, and that is the whole point: the bar is
     painted across the bottom of the room, and the near edge of the FLOOR is under it. The ball
     comes to rest at z=0.88 and a poo pile sits at 0.80, both of which draw inside this strip -
     so a bar that grabbed its own rectangle first would eat the very tap that starts a slingshot.
     Anything you can pick up gets first refusal; the bar takes what is left. */
  /* THE BED, AFTER THE DOG. It used to be tested first, which was harmless while it was a basket
     against the back wall that he never stood on. It is a rug in the middle of the floor now and
     he sleeps in the middle of it, so testing it first would mean every tap on a sleeping dog hit
     the rug underneath him and woke him instead of stroking him. He gets first refusal; the bed
     takes what is left. */
  if(inRect(FR.bed,4,10)){
    if(S.bedTier===0){
      S.bedHinted=true;
      toast("HE HAS NOWHERE PROPER TO SLEEP \u2014 SEE THE LIST",1);
      beep(300,.1);
      renderTodo(); $("#todoPanel").classList.add("show");
      return;
    }
    if(!bedAdequate()){
      openChoice("HE'S OUTGROWN HIS BED",
        "IT'S TOO SMALL FOR HIM NOW \u2014 HE WON'T GET A FULL NIGHT'S REST.<br><br>UPGRADE TO A BIGGER BED?",
        "BIGGER BED \u2014 $45", ()=>buyBiggerBed(),
        "NOT NOW", ()=>toggleRest());
      beep(300,.1); return;
    }
    toggleRest(); return;
  }
  if(fy>0.86){ xpBarTap(); return; }
  // empty room: nothing — the whistle button calls him now
});
$("#dogcv").addEventListener("pointermove",e=>{
  const r=e.currentTarget.getBoundingClientRect();
  const fx=(e.clientX-r.left)/r.width, fy=(e.clientY-r.top)/r.height;
  if(BRUSH.held){
    BRUSH.x=fx; BRUSH.y=fy;
    if(fx>CAM.x-0.02 && fx<CAM.x+CAMDWF+0.04 && fy>0.30 && fy<0.85 && !R.active && !OUTING.active && !PK.active){
      const was=S.groom;
      S.groom=clamp(S.groom+0.32,0,100);
      S.mood=clamp(S.mood+0.05,0,100);
      // loose fur lifts off him as he is worked over — the payoff is the feel, not the XP
      if(Math.random()<0.55){
        SUDS.push({x:fx+(Math.random()-0.5)*0.05, y:fy+(Math.random()-0.5)*0.04,
                   life:0.55+Math.random()*0.5, r:1.5+Math.random()*4});
        if(SUDS.length>60) SUDS.splice(0,SUDS.length-60);
      }
      // bristle rasp, pitched up as his coat comes good
      if(Math.random()<0.16) beep(170+S.groom*1.2+Math.random()*60, .03, "square", .012);
      // a chime at each quarter so progress reads without paying out
      for(const mark of [25,50,75]) if(was<mark && S.groom>=mark){ beep(560+mark*3,.05); heartsBurst(1); }
      if(S.groom>=100 && !BRUSH.rew){
        BRUSH.rew=true; addXP(6); heartsBurst(2);
        toast("WELL GROOMED. HE LOOKS SHARP."); beep(880,.08);
      }
    }
    return;
  }
  if(SPONGE.held){
    SPONGE.x=fx; SPONGE.y=fy;
    if(Math.random()<0.4){ DRIPS.push({x:fx+(Math.random()-0.5)*0.015,y:fy+0.015,vy:0.12+Math.random()*0.18,life:0.5+Math.random()*0.3}); if(DRIPS.length>50) DRIPS.splice(0,DRIPS.length-50); }
    if(fx>CAM.x-0.02 && fx<CAM.x+CAMDWF+0.04 && fy>0.30 && fy<0.85 && !R.active && !OUTING.active && !PK.active && S.shampooPct>0){
      S.clean=clamp(S.clean+0.6,0,100); WASH.heat=0.5;
      S.shampooPct=clamp(S.shampooPct-0.2,0,100);
      if(Math.random()<0.5){ SUDS.push({x:fx,y:fy,life:0.9,r:3+Math.random()*5}); if(SUDS.length>60) SUDS.splice(0,SUDS.length-60); }
      if(S.clean>=100 && !SPONGE.rew){
        SPONGE.rew=true; addXP(6); heartsBurst(2);
        tickTodo("d_clean");
        toast("SQUEAKY CLEAN!"); beep(880,.08);
      }
    }
    return;
  }
  if(PET.down && !WASH.active && !BALL.held){
    const onDog = fx>CAM.x-0.02 && fx<CAM.x+CAMDWF+0.04 && fy>0.30;
    if(onDog){
      if(Math.hypot(fx-PET.px, fy-PET.py)>0.02){
        PET.stroked=true; clearTimeout(PET.lp);
        PET.px=fx; PET.py=fy;
        petStroke(0.15);
      }
    } else { PET.stroked=true; clearTimeout(PET.lp); }
  }
  if(WASH.active){
    if(fx>CAM.x-0.02 && fx<CAM.x+CAMDWF+0.04 && fy>0.30 && fy<0.85){
      S.clean=clamp(S.clean+0.7,0,100); WASH.heat=0.4;
      if(Math.random()<0.5) SUDS.push({x:fx,y:fy,life:0.9,r:3+Math.random()*5});
    }
    return;
  }
  if(!BALL.held) return;
  /* The finger names a spot on the FLOOR. Pulling it down the glass walks the ball toward you and
     it grows on the way; pushing it up sends it back toward the wall and it shrinks. That is the
     entire depth gesture, and it falls out of the projection rather than being special-cased. */
  /* OUT OF THE ROOM ALTOGETHER. fy is measured against the DOGCAM, so fy>1 is a finger below it,
     on the black deck - and the first frame that happens is the lock. */
  const G=slingGeom();
  if(G && SLING.on && (fy>1 || SLING.deck)){
    // ...and it cannot be dragged off the picture, in either direction
    SLING.dx=clamp(G.left+fx*G.cw, 8, G.gw-8);
    SLING.dy=clamp(G.top+fy*G.ch, G.lockY, G.botY);
    if(!SLING.deck){
      SLING.deck=true;
      SLING.lockX=BALL.x; SLING.lockZ=BALL.z;         // the throw leaves from HERE, whatever
      SLING.lockSX=G.left+rmX(BALL.x,BALL.z)*G.cw;    // ...and the band is pinned to the split
      SLING.lockSY=G.lockY;
      SLING.peakPull=0; SLING.maxed=false;
      BALL.tx=BALL.x; BALL.tz=BALL.z;                 // stop the in-room lerp dead
      sfxSlingLock();
    }
    SLING.pull=slingDeckPull(SLING.dy,G);
    if(SLING.pull>SLING.peakPull+SLING_DECK_NOTCH){
      SLING.peakPull=SLING.pull; slingCreak(SLING.pull);
    }
    if(SLING.pull>0.97 && !SLING.maxed){ SLING.maxed=true; sfxSlingMax(); }
    return;
  }
  // ...but not past the bottom of the picture. rmY(1) is BELOW the canvas, so an unclamped pull
  // parks the ball under the XP bar where you cannot see the thing you are aiming.
  BALL.tz=Math.min(0.92, rmZof(clamp(fy,ROOM.backY+0.01,0.995)));
  BALL.tx=rmXof(clamp(fx,0.02,0.98), BALL.tz);
  // ...and stretch the band. Every fresh notch of pull earns one creak; slack does not un-creak,
  // so easing off and pulling again through ground you already covered stays quiet.
  SLING.x=fx; SLING.y=fy;
  SLING.draw=Math.min(SLING_MAX, Math.hypot(fx-SLING.ax, fy-SLING.ay));
  if(SLING.draw>SLING.peak+SLING_NOTCH){ SLING.peak=SLING.draw; slingCreak(slingPow()); }
});
/* ==================== TWO GESTURES ON THE DOG ====================
   Read on release, off the whole travel from where the finger went down - not off the last frame,
   which is a flick and not a swipe. Down is SIT, sideways is ROLL, and each only exists once he
   has been taught it. A stroke that wanders is still a stroke: the gesture has to clear a real
   distance and be decisively one axis or the other, or petting him would set him rolling. */
const GEST_MIN=0.085;      // fraction of the glass the finger has to actually cover
const GEST_AXIS=1.5;       // ...and how much one axis must beat the other
function dogGesture(fx,fy){
  const dx=fx-(PET.sx===undefined?fx:PET.sx), dy=fy-(PET.sy===undefined?fy:PET.sy);
  const ax=Math.abs(dx), ay=Math.abs(dy);
  if(Math.max(ax,ay)<GEST_MIN) return null;
  if(ay>ax*GEST_AXIS && dy>0) return "sit";
  // ...and WHICH WAY sideways: a dog rolling over travels, and it travels the way you swiped
  if(ax>ay*GEST_AXIS)         return dx<0 ? "rollL" : "rollR";
  return null;
}
function dogCanTrick(){
  return !R.active && !OUTING.active && !PK.active && !WASH.active && !PARTY.on &&
         CAM.state!=="leap" && CAM.state!=="rest" && CAM.state!=="roll" &&
         CAM.state!=="fetch" && CAM.state!=="come" && !CAM.bedTarget;
}
function dogDoSit(){
  if(!dogCanTrick()) return false;
  CAM.state="begwait"; CAM.t=0; CAM.until=3.2+Math.random()*1.6; CAM.fi=0; CAM.lz=0;
  S.mood=clamp(S.mood+3,0,100); addXP(2); tickTodo("j_trick");
  toast("SIT! GOOD BOY."); beep(620,.06); setTimeout(()=>beep(880,.08),90);
  heartsBurst(1); haptic(20);
  return true;
}
/* HOW FAR HE TRAVELS ROLLING. He used to spin on the spot, which is not what rolling over is -
   a dog going over on his back carries his own momentum across the carpet. The distance is eased
   in and out over the roll's own clock, so he gathers and settles rather than sliding at a
   constant rate, and it is clamped to the floor so he cannot roll through a wall. */
const ROLL_TRAVEL=0.19;        // floor units covered by one full roll
function dogDoRoll(dir){
  if(!dogCanTrick()) return false;
  CAM.state="roll"; CAM.t=0; CAM.until=ROLL_T; CAM.fi=0; CAM.lz=0; CAM.rollT=0;
  CAM.rollDir = dir<0 ? -1 : 1;
  CAM.rollX0 = CAM.x;
  CAM.dir = CAM.rollDir;
  S.mood=clamp(S.mood+4,0,100); S.fun=clamp(S.fun+5,0,100); addXP(3); tickTodo("j_trick");
  toast("ROLL OVER! WHAT A DOG."); beep(520,.07); setTimeout(()=>beep(700,.07),110);
  setTimeout(()=>beep(940,.10),220);
  heartsBurst(2); haptic(28);
  return true;
}
$("#dogcv").addEventListener("pointerup",e=>{
  if(WINGES.on){
    const r=e.currentTarget.getBoundingClientRect();
    if(winGestureEnd((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height, r.height)) return;
  }
  if(PET.down && !WASH.active){
    const r=e.currentTarget.getBoundingClientRect();
    const g=dogGesture((e.clientX-r.left)/r.width, (e.clientY-r.top)/r.height);
    if(g==="sit"  && hasTrick("sit")  && dogDoSit())  { PET.down=false; clearTimeout(PET.lp); return; }
    if((g==="rollL"||g==="rollR") && hasTrick("roll") && dogDoRoll(g==="rollL"?-1:1))
      { PET.down=false; clearTimeout(PET.lp); return; }
  }
  if(PET.down && !PET.stroked) openStatus();   // quick tap on BONES = his needs
  if(BALL.held) ballRelease();
  BALL.held=false; PET.down=false; SPONGE.held=false; BRUSH.held=false; clearTimeout(PET.lp);
});
$("#dogcv").addEventListener("pointercancel",()=>{ BALL.held=false; SLING.on=false; SLING.deck=false; PET.down=false; SPONGE.held=false; BRUSH.held=false; WINGES.on=false; clearTimeout(PET.lp); });
$("#stClose").onclick=closeStatus;
$("#meters").addEventListener("click",()=>{
  closeStatus();
  $("#home .body").scrollTop=0;
  toast("QUICK CARE IS BELOW THE MAIN BUTTONS");
  beep(500,.05);
});
$("#portrait").addEventListener("pointerdown",hidePortrait);


