$("#rSnack").onclick=()=>{ if(S.money<3) return toast("NO MONEY",1);
  S.money-=3; S.hunger=clamp(S.hunger+22,0,100); beep(520); toast("REMOTE BONE DISPENSED"); renderMeters(); };
$("#rWalk").onclick=()=>{ if(S.money<5) return toast("NO MONEY",1);
  S.money-=5; S.mood=clamp(S.mood+18,0,100); S.clean=clamp(S.clean-4,0,100); beep(640); toast("DOGWALKER BOOKED"); renderMeters(); };
// DOGPARK performance leans on energy and mood (see startPark's spd formula) — a dog running on
// empty is visibly slower out there, so warn before he wastes a run being sluggish rather than
// let the player find out mid-wave. Whichever of energy/hunger/mood is worst picks the wording.
function pkFitnessWarning(){
  const cands=[{v:S.energy,word:"TIRED"},{v:S.hunger,word:"HUNGRY"},{v:S.mood,word:"DOWN"}];
  cands.sort((a,b)=>a.v-b.v);
  return cands[0].v<40 ? cands[0].word : null;
}
const DOGPARK_UNLEASHED_COST=5000;   // bones needed to unlock DOGPARK UNLEASHED
/* UNLEASHED IS A NIGHT DOOR. "Under cover of night" was always the copy; now it is the rule.
   The window is read straight off MOON_RISE/MOON_SET — the same pair the dusk fade ends on and
   the moon starts climbing at — so the sky outside and the door on the home screen can never
   disagree about whether it is night. REGULAR is untouched and open at every hour. */
function unleashedHoursOk(){ return CLK.h>=MOON_RISE || CLK.h<MOON_SET; }
function unleashedHoursTxt(){
  return String(MOON_RISE).padStart(2,"0")+":00 \u2014 0"+MOON_SET+":00";
}
function unleashedHoursDeny(){
  beep(160,.15,"sawtooth",.05);
  toast("DOGPARK UNLEASHED IS ONLY OPEN AT NIGHT \u2014 "+unleashedHoursTxt()+". IT IS "
        +String(Math.floor(CLK.h)).padStart(2,"0")+":00.",1);
}
function reallyEnterDogpark(){
  const unlocked=S.snacks>=DOGPARK_UNLEASHED_COST;
  const night=unleashedHoursOk();
  openChoice("CHOOSE YOUR PARK",
    "DOGPARK UNLEASHED REPEATS THE SAME 10 WAVES UNDER A DARKER NIGHT SKY WITH DOUBLE THE ENEMIES ON SCREEN AT ONCE."
      +"<br><br>CLEAR <b>WAVE 10</b> THERE AND <b>WOLFIE</b> COMES UP. PUT HIM DOWN AND HIS HOLE STAYS OPEN \u2014 THAT IS WHERE BONES BECOME XP."
      +(unlocked?"":"<br><br>\ud83d\udd12 UNLOCKS AT "+DOGPARK_UNLEASHED_COST+" BONES.")
      +(night?"":"<br><br>\ud83c\udf1a <b>ONLY AT NIGHT</b> \u2014 "+unleashedHoursTxt()+"."),
    "REGULAR", ()=>{ toast("SURVIVE THE WAVES, BANK BIG XP. IF BONES GETS CAUGHT, YOU LOSE IT ALL \u2620\ufe0f",1); startPark(false); },
    /* Two locks, and the button names the one you are actually behind: a player at 6000 bones
       standing in daylight is told the hour, not the price he has already paid. */
    (!unlocked?"\ud83d\udd12 DOGPARK UNLEASHED":(night?"DOGPARK UNLEASHED":"\ud83c\udf1a DOGPARK UNLEASHED")),
    ()=>{
      if(!unlocked){ beep(160,.15,"sawtooth",.05); toast("NEEDS "+DOGPARK_UNLEASHED_COST+" BONES TO UNLOCK \u2014 YOU HAVE "+S.snacks,1); return; }
      if(!unleashedHoursOk()){ unleashedHoursDeny(); return; }
      toast("DOGPARK UNLEASHED \u2014 DOUBLE THE ENEMIES, SAME WAVES, UNDER COVER OF NIGHT.",1);
      openCarry();
    },
    "\u2190 BACK", null);
}

/* ==================== TAKING BONES IN =======================================================
   UNLEASHED is the risk mode, and until now the only thing at risk in it was the run itself: you
   walked in empty-handed every time and the wallet at home never entered into it. The hole eats
   bones, the hole is how a run becomes levels, and the fastest way to a big level jump is to walk
   in already carrying a hoard - so this is where the wallet is put on the table.
   It is a real gamble and it is stated as one on the panel: die out there and 90% of everything
   he is carrying, brought-in bones included, stays in the grass. */
let CARRY_N=0;
function carryMax(){ return Math.floor(S.snacks/BURY_UNIT)*BURY_UNIT; }   // whole shovels only
function carrySet(n){
  CARRY_N=clamp(Math.round(n/BURY_UNIT)*BURY_UNIT, 0, carryMax());
  const r=$("#carryRange"); if(r && +r.value!==CARRY_N) r.value=CARRY_N;
  const el=$("#carryNum"); if(el) el.textContent=CARRY_N+" BONES";
  const ln=$("#carryLines");
  if(ln){
    const pr=buryProject(CARRY_N);
    ln.innerHTML =
      "HE HAS <b>"+S.snacks+"</b> BONE TREAT"+(S.snacks===1?"":"S")+" AT HOME."+
      "<br><br>WHAT HE CARRIES IN CAN BE FED TO <b>WOLFIE'S HOLE</b> OUT THERE — "+
      (CARRY_N>0 ? "<b>+"+pr.xp+" XP</b>, ABOUT <b>"+pr.levels+" LEVEL"+(pr.levels===1?"":"S")+"</b>."
                 : "worth <b>+"+Math.round(xpNeed(S.lvl)*BURY_XP_PCT*100)/100+" XP</b> A BONE.")+
      "<br><br>☠️ IF HE GOES DOWN OUT THERE, <b>90% OF IT STAYS IN THE GRASS.</b>";
  }
}
function openCarry(){
  const mx=carryMax();
  if(mx<BURY_UNIT){                       // nothing worth carrying: don't put a dead panel up
    CARRY_N=0;
    toast("NO SPARE BONES TO CARRY IN — GOING IN LIGHT.",1);
    startPark(true); return;
  }
  const r=$("#carryRange"); r.max=mx; r.step=BURY_UNIT;
  carrySet(Math.min(CARRY_N||0, mx));
  $("#carry").classList.add("show");
  beep(520,.05);
}
function closeCarry(){ $("#carry").classList.remove("show"); }
$("#carryRange").oninput=e=>{ carrySet(+e.target.value); beep(420+CARRY_N%200,.012,"square",.012,{key:"carrysl"}); };
$("#carryNone").onclick=()=>{ carrySet(0); beep(360,.05); };
$("#carryQ").onclick   =()=>{ carrySet(carryMax()*0.25); beep(480,.05); };
$("#carryH").onclick   =()=>{ carrySet(carryMax()*0.5);  beep(560,.05); };
$("#carryAll").onclick =()=>{ carrySet(carryMax());      beep(680,.05); };
$("#carryBack").onclick=()=>{ closeCarry(); CARRY_N=0; reallyEnterDogpark(); };
$("#carryGo").onclick  =()=>{
  closeCarry();
  if(CARRY_N>0){ toast("CARRYING "+CARRY_N+" BONES INTO THE DARK.",1); haptic([25,35,60]); }
  beep(660,.08); setTimeout(()=>beep(880,.1),90);
  startPark(true);
};

/* The pitch, from the burial side rather than the park side: someone tapping the wallet wants
   XP, and this is the one route to it. Kept to three lines — the long version lives in
   reallyEnterDogpark, and saying it twice at full length is how a menu becomes a wall. */
function pkUnleashedAdvice(){
  openChoice("DOGPARK UNLEASHED",
    "<b>HARDCORE.</b> DOUBLE THE ENEMIES, UNDER COVER OF NIGHT.<br><br>"+
    "<b>MORE OF THEM</b> \u2014 SAME 10 WAVES, TWICE THE PRESSURE.<br><br>"+
    "<b>TRADE BONES FOR XP</b> \u2014 CLEAR WAVE 10, PUT <b>WOLFIE</b> DOWN, AND HIS HOLE STAYS OPEN FOR GOOD."+
    (unleashedHoursOk()?"":"<br><br>\ud83c\udf1a <b>ONLY AT NIGHT</b> \u2014 "+unleashedHoursTxt()+"."),
    unleashedHoursOk()?"GO":"\ud83c\udf1a GO",
    ()=>{ if(!unleashedHoursOk()){ unleashedHoursDeny(); return; } openCarry(); },
    "NOT NOW", null);
  beep(520,.05);
}
$("#bWalk").onclick=()=>{
  if(S.lvl<5) return toast("THE DOGPARK UNLOCKS AT LV.5",1);
  if(S.sick && !isVamp()) return toast("BONES IS TOO SICK FOR THE PARK",1);
  const warnWord=pkFitnessWarning();
  if(warnWord){
    openChoice("BONES LOOKS "+warnWord,
      "HE WON'T BE AT HIS BEST OUT THERE LIKE THIS \u2014 SLOWER THAN USUAL IN THE PARK.<br><br>ARE YOU SURE YOU WANT TO GO?",
      "GO ANYWAY", reallyEnterDogpark,
      "TAKE CARE OF HIM FIRST", null);
    return;
  }
  reallyEnterDogpark();
};
function openSupplies(){ renderSupplies(); $("#supplies").classList.add("show"); }
function renderSupplies(){
  const it=(icon,name,tiny,key,owned)=>'<div class="prow'+(owned===false?' locked':'')+'" data-it="'+key+'"><span class="nm">'+icon+' '+name+'<br><span class="tiny">'+tiny+'</span></span></div>';
  $("#suppliesList").innerHTML =
    it(icn("water"),"WATER BOWL","TAP TO POUR \u2014 FREE. HE DRINKS WHEN THIRSTY","water")+
    it(icn("food"),"FOOD BOWL","POUR KIBBLE (x"+S.kibble+" LEFT) \u2014 3 POURS FILL","food")+
    (S.shampooPct>0
      ? it(icn("sponge"),"SPONGE","DRAG OFF THE WALL \u2014 SCRUB HIM CLEAN","sponge")
      : it(icn("sponge"),"SPONGE","NEEDS SHAMPOO \u2014 FIND IT IN THE SHOP","spongebuy",false))+
    (S.bedTier===0
      ? it(icn("bed"),"DOG BED","NOT OWNED \u2014 FIND IT IN THE SHOP","bedbuy",false)
      : bedAdequate()
        ? it(icn("bed"),"DOG BED ("+bedTierName(S.bedTier)+")","TAP THE BED \u2014 FULL REST","bed")
        : it(icn("bed"),"DOG BED ("+bedTierName(S.bedTier)+")","HE'S OUTGROWN IT \u2014 UPGRADE IN SHOP","bedbuy",false))+
    (S.shampooOwned ? it(pctIcon(S.shampooPct),"DOG SHAMPOO "+Math.round(S.shampooPct)+"%","BATHS USE IT UP \u2014 RESTOCK IN THE SHOP","shampooinfo") : "")+
    it(icn("kibble"),"KIBBLE x"+S.kibble,"RESTOCK IN THE SHOP","food")+
    it(icn("snack"),"BONE TREATS x"+S.snacks,"GIVE ONE FROM NOURISH BONES","snack")+
    (S.ballOwned ? '<div class="prow"><span class="nm">'+icn("ball")+' SPARE BALLS x'+S.ballStock
      +'<br><span class="tiny">SET ONE DOWN IF HIS CURRENT ONE IS LOST OR STUCK</span></span>'
      +'<button data-supact="ball" '+(S.ballStock<=0?"disabled":"")+'>SET DOWN</button></div>' : "")+
    // left behind the first time the mysterious dog did business with you — blow it and he comes
    (S.mystMet ? '<div class="prow" style="border-color:#e8c14a"><span class="nm" style="color:#e8c14a">◎ DOG WHISTLE'
      +'<br><span class="tiny">NOBODY ELSE HEARS IT. HE DOES.</span></span>'
      +'<button data-supact="whistle">BLOW IT</button></div>' : "");
}
$("#shopSup").addEventListener("click",e=>{
  const t=e.target.closest("button"); if(!t) return;
  if(t.dataset.sup==="kibble"&&S.money>=2){ S.money-=2; S.kibble++; beep(600,.05); }
  if(t.dataset.sup==="bed") buyBed();
  if(t.dataset.sup==="biggerbed") buyBiggerBed();
  if(t.dataset.sup==="ball"){ buyBall(); }
  if(t.dataset.sup==="brush"&&S.money>=18&&!S.brushOwned){ S.money-=18; S.brushOwned=true; beep(660,.07); setTimeout(()=>beep(880,.09),100); toast("A DOG BRUSH. IT HANGS BY THE SPONGE."); }
  if(t.dataset.sup==="hoop"&&S.money>=40&&!S.hoopOwned){ S.money-=40; S.hoopOwned=true; beep(880,.08); setTimeout(()=>beep(1170,.1),100); toast("HOOP MOUNTED BY THE WINDOW. SWISH \u2014 +1 XP A BASKET."); }
  if(t.dataset.sup==="shampoo"&&S.money>=5&&S.shampooPct<100){ S.money-=5; S.shampooOwned=true; S.shampooPct=100; beep(700,.07); setTimeout(()=>beep(950,.09),100); toast("SHAMPOO TOPPED UP \u2014 TIME FOR A BATH!"); }
  if(t.dataset.sup==="snack"&&S.money>=3){ S.money-=3; S.snacks++; beep(600,.05); }
  if(t.dataset.sup==="robot"&&S.money>=350&&!S.owned.robot){ S.money-=350; S.owned.robot=true; beep(660,.08); setTimeout(()=>beep(880,.08),120); setTimeout(()=>beep(1100,.1),240); toast("NOURISH-BOT INSTALLED! BONES EATS AND DRINKS WHILE YOU WORK."); }
  // HOMEWARE — each of these owns its own price check and toast, so the shop row is just a button
  if(t.dataset.sup==="blinds")   buyBlinds();
  if(t.dataset.sup==="blackout") buyBlackout();
  renderMeters(); renderShop();
});
