$("#devLitterNow").onclick=()=>{
  if(S.litter){ toast("BONES ALREADY HAS A PUP WAITING (DEV)",1); return; }
  S.litter=true; heartsBurst(5); beep(700,.08); setTimeout(()=>beep(900,.1),110);
  toast("A LITTER! ONE PUP WILL CARRY THE LEGACY. (DEV)");
};
