function drawBone(ctx,x,y,s,color){
  ctx.fillStyle=color;
  ctx.fillRect(x-5*s, y-1.5*s, 10*s, 3*s);
  ctx.beginPath();
  ctx.arc(x-5*s,y-2*s,2.2*s,0,7); ctx.arc(x-5*s,y+2*s,2.2*s,0,7);
  ctx.arc(x+5*s,y-2*s,2.2*s,0,7); ctx.arc(x+5*s,y+2*s,2.2*s,0,7);
  ctx.fill();
}
function drawStarIcon(ctx,x,y,r){
  ctx.save(); ctx.translate(x,y);
  ctx.fillStyle="#ffe98a"; ctx.strokeStyle="#a9770a"; ctx.lineWidth=1.5;
  ctx.beginPath();
  for(let i=0;i<5;i++){
    const a=-Math.PI/2+i*2*Math.PI/5, a2=a+Math.PI/5;
    ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
    ctx.lineTo(Math.cos(a2)*r*0.42, Math.sin(a2)*r*0.42);
  }
  ctx.closePath(); ctx.fill(); ctx.stroke();
  ctx.restore();
}
function drawRegenIcon(ctx,x,y,r){
  ctx.save(); ctx.translate(x,y);
  ctx.fillStyle="#3fdc7a"; ctx.strokeStyle="#0a5c2c"; ctx.lineWidth=1.5;
  const a=r*0.34;
  ctx.beginPath();
  ctx.moveTo(-a,-r*0.9); ctx.lineTo(a,-r*0.9); ctx.lineTo(a,-a); ctx.lineTo(r*0.9,-a);
  ctx.lineTo(r*0.9,a); ctx.lineTo(a,a); ctx.lineTo(a,r*0.9); ctx.lineTo(-a,r*0.9);
  ctx.lineTo(-a,a); ctx.lineTo(-r*0.9,a); ctx.lineTo(-r*0.9,-a); ctx.lineTo(-a,-a);
  ctx.closePath(); ctx.fill(); ctx.stroke();
  ctx.restore();
}
function drawMagnetIcon(ctx,x,y,r){
  ctx.save(); ctx.translate(x,y);
  ctx.strokeStyle="#e23"; ctx.lineWidth=3; ctx.lineCap="round";
  ctx.beginPath(); ctx.arc(0,1,r*0.65,Math.PI*0.15,Math.PI*0.85); ctx.stroke();
  ctx.strokeStyle="#ddd"; ctx.lineWidth=3;
  ctx.beginPath(); ctx.moveTo(-r*0.62,1); ctx.lineTo(-r*0.62,-r*0.55); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(r*0.62,1); ctx.lineTo(r*0.62,-r*0.55); ctx.stroke();
  ctx.restore();
}
function drawLock(ctx,x,y,s,color){
  ctx.strokeStyle=color; ctx.lineWidth=2*s;
  ctx.beginPath(); ctx.arc(x,y-2.5*s,3*s,Math.PI,0); ctx.stroke();
  ctx.fillStyle=color; ctx.fillRect(x-4*s,y-3*s,8*s,7*s);
}
// tap the bones counter any time (not just between waves) to cash spare bones in for something
// useful back in the main hub — deliberately a worse rate than just letting kills bank XP
// normally, so it's a way to not waste leftover bones rather than a primary strategy
/* Bones are currency, not a slow XP drip: nothing about picking one up grants XP any more.
   The only ways a run becomes levels are the kills and side objectives the bank pays out, and
   this — deliberately burying a pile, which is a choice with a visible price. */
/* THE RATE, IN EXACTLY ONE PLACE - and it is a PERCENTAGE now, not two flat XP a shovel.
   A flat rate meant burying scaled backwards: 200 bones was a fifth of a level at level 3 and a
   rounding error at level 40, so the one thing UNLEASHED is FOR - going in deep, coming out with
   a hoard, and gambling it at the hole - paid less the further you got. At half a percent of the
   current level's requirement per bone, 200 bones is exactly one level at every level, forever.
   That is the whole point of the mode: the extra craziness, and the risk of a big jump. */
const BURY_UNIT=10;
const BURY_XP_PCT=0.005;                              // ...per BONE. 200 bones = one level.
/* What one shovel of BURY_UNIT bones is worth RIGHT NOW. Read live, per shovel, so a burial that
   levels him mid-pour re-bases onto the new level's requirement instead of paying out a whole
   hoard at the cheap rate it started at.
   IT IS NOT ROUNDED, and that is the difference between the rule holding and nearly holding.
   xpNeed is itself fractional (level 3 needs 49.5), so rounding a shovel to whole XP loses up to
   half a point nineteen times over: 200 bones came to 40 XP against a level of 49.5 and bought
   nothing at all, while the same 200 bones at level 25 - where the arithmetic happens to come out
   whole - bought exactly one. A rule that only works at the levels where the numbers are round is
   not a rule. S.xp has always been able to hold a fraction (it is what is left after subtracting a
   fractional xpNeed), so nothing downstream had to change. */
function buryXPPerShovel(){ return xpNeed(S.lvl)*BURY_XP_PCT*BURY_UNIT; }
/* HAS HE MADE THE LEVEL. An epsilon, and it is not defensive padding - it is load-bearing.
   Twenty shovels of exactly a twentieth of a level is exactly a level in arithmetic and
   347.99999999999994 against 348 in binary floating point, so at level 12 a 200-bone burial came
   up one ulp short and bought nothing. A player would have read that as the game eating their
   hoard, and it would have been true at some levels and not others with no way to tell which.
   Everything that levels off a fractional award goes through here. */
function xpMet(cur,lvl){ return cur >= xpNeed(lvl)-1e-9; }
/* THE ESTIMATE ON THE BUTTON IS A PROMISE, so both halves of it come out of one simulation of the
   actual climb: the rate depends on the level and the level depends on the rate. Two functions
   working this out separately would agree right up until the first burial that crosses a level
   boundary, which is precisely the burial anyone cares about. */
function buryProject(n){
  const shovels=Math.floor(n/BURY_UNIT);
  let lvl=S.lvl, cur=S.xp, xp=0, gains=0;
  for(let i=0;i<shovels;i++){
    if(lvl>=LVL_CAP) break;
    const give=xpNeed(lvl)*BURY_XP_PCT*BURY_UNIT;    // unrounded, same as the live award
    xp+=give; cur+=give;
    while(lvl<LVL_CAP && xpMet(cur,lvl)){ cur=Math.max(0,cur-xpNeed(lvl)); lvl++; gains++; }
  }
  return {xp:Math.round(xp), levels:gains};          // rounded ONCE, for the label only
}
function xpFromBury(n){ return buryProject(n).xp; }
// how many levels a given lump of XP would ACTUALLY deliver from where he stands right now —
// never promises one it cannot pay, so the estimate on the button is a promise, not a guess
function pkLevelsFromXP(xp){
  let lvl=S.lvl, cur=S.xp, left=xp, gains=0;
  while(left>0 && lvl<LVL_CAP){
    const need=xpNeed(lvl)-cur;
    if(left<need-1e-9) break;              // same epsilon, same reason as xpMet
    left-=need; lvl++; cur=0; gains++;
  }
  return gains;
}
// everything he is carrying, rounded down to whole burials
function buryAll(){ return buryAllFor("park"); }
function burySub(){ return burySubFor("park"); }
