/* THE ONE PLACE THE WALLET IS DEBITED, and it is inside the Object.assign that starts the run so
   the bones cannot be taken by a path that then fails to start one. REGULAR never carries: the
   picker is not offered there and this returns 0, so the two modes cannot drift. */
function carryTake(plus){
  if(!plus) { CARRY_N=0; return 0; }
  const n=clamp(Math.round(CARRY_N/BURY_UNIT)*BURY_UNIT, 0, Math.floor(S.snacks/BURY_UNIT)*BURY_UNIT);
  CARRY_N=0;
  if(n>0){ S.snacks-=n; dogLog("CARRIED "+n+" BONES INTO UNLEASHED"); }
  return n;
}
